(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["sq"] = {"ui":{"skip":"Kalo te përmbajtja","back":"← Kthehu te AI-gile","lang.button":"Gjuha: {name}","lang.dialog":"Zgjidh një gjuhë","lang.search":"Kërko gjuhë","lang.none":"Asnjë gjuhë nuk përputhet","lang.notYet":"{name} nuk është përkthyer ende","theme.aria":"Ndrysho temën: e çelët, e errët ose e zezë","theme.toLight":"Kalo te tema e çelët","theme.toDark":"Kalo te tema e errët","theme.toBlack":"Kalo te tema e zezë (e zezë e vërtetë, e butë për ekranet OLED)","words.underline":"Nënvizo këto fjalë në faqe","words.underlineHelp":"Kalo miun mbi një fjalë me pika ose preke, për të parë çfarë do të thotë.","words.col.todo":"Karta të zgjedhura për tani: ekipi do të nisë me këto më pas.","words.col.doing":"Një AI po punon pikërisht tani në këtë kartë.","words.col.review":"Një AI e ka kryer punën; një tjetër e kontrollon përpara se të të arrijë ty.","words.col.verify":"Të pret ty: provoje dhe thuaj nëse funksionon.","words.col.team":"Shënimet ose përgjigjet e tua, që presin ekipin t'i marrë.","words.col.done":"Përfunduar dhe pranuar.","index.title":"AI-gile: ekipi yt AI i zhvillimit, në një tabelë","index.description":"AI-gile është një tabelë kanban për ekipet e programimit me AI. Ata punojnë ndërsa ti fle; ti merr një grumbull të shkurtër gjërash për t'i vendosur, provuar dhe pranuar.","hero.logoAlt":"Ikona e tabelës AI-gile","hero.h1.html":"Ekipi yt AI i zhvillimit, në një&nbsp;tabelë.","hero.alpha":"🐣 Para-alfa e mbyllur","hero.alphaTitle":"E hershme dhe e papërfunduar: faleminderit që e provon!","hero.lede":"Ata ndërtojnë ndërsa ti fle. Zgjohesh me një grumbull të shkurtër: disa pyetje, disa gjëra për t'u provuar, një ose dy diamante vjollcë. Kliko, prano dhe kthehu te kafja.","dl.windows":"Aplikacioni për Windows","dl.browser":"Hape në shfletues","dl.messenger":"📱 Messenger për telefonin tënd","dl.soon":"Së shpejti","dl.notify":"🔔 Më njofto kur hapet","dl.notifySmall":"Alfa ose beta","hero.secondary":"Agjile, por ekipi nuk ka kurrë nevojë për kafen e mbledhjes së shkurtër. (Mbledhjet i bëjnë gjithsesi.)","pitch.h2":"AI-gile me sa fjalë të duash","pitch.lede":"Zgjidh një gjatësi, nga një fjalë deri në 144. Çdo gjatësi është përshkrim më vete, shkruar posaçërisht për të. Tërhiq rrëshqitësin ose përdor shigjetat.","pitch.rangeLabel":"Gjatësia në fjalë","pitch.dice":"🎲 version tjetër","pitch.words.one":"{n} fjalë","pitch.words.other":"{n} fjalë","pitch.letters.one":"{n} shkronjë","pitch.letters.other":"{n} shkronja","pitch.chars.one":"{n} karakter","pitch.chars.other":"{n} karaktere","count.line.html.one":"{n} kartë është tani në tabelë","count.line.html.other":"{n} karta janë tani në tabelë","people.humans.html.one":"👥 {n} njeri","people.humans.html.other":"👥 {n} njerëz","people.agents.html.one":"🤖 {n} agjent","people.agents.html.other":"🤖 {n} agjentë","people.working.html.one":"⚡ {n} në punë tani","people.working.html.other":"⚡ {n} në punë tani","pre.title":"AI-gile: diçka po ndërtohet","pre.description":"Këtu po ndërtohet diçka: një tabelë ku ekipe AI ndërtojnë atë që kërkon dhe të mësojnë gjatë rrugës. Për tani, para-alfa e mbyllur me miq.","pre.h1":"Këtu po ndërtohet diçka. 🤫","pre.line":"Një tabelë ku ekipe AI ndërtojnë atë që kërkon dhe të mësojnë gjatë rrugës. Për tani, para-alfa e mbyllur me miq.","pre.btn":"🔔 Më njofto kur hapet","pre.peek":"Pas xhamit: tabela e vërtetë, drejtpërdrejt. Çdo kartë është një shirit me ngjyrë.","pre.peekFake":"Pas xhamit: kështu duket një tabelë në punë.","pre.night":"🌙 Rojtari i natës është përgjegjës · 😴 njeriu po pushon","features.aria":"Çfarë bën","f.pile.h":"Një grumbull për ty","f.pile.html":"<b>Për ty</b> mbledh gjithçka që të pret, nga të gjitha projektet: pyetje, gjëra për t'u provuar, detyra që i bën vetëm një njeri. Radha jote të tregon çfarë vjen më pas dhe sa zgjat.","f.sleep.h":"Ekipe që punojnë ndërsa ti fle","f.sleep.p":"Çdo projekt ka një drejtues dhe një ekip agjentësh AI. Shkruaj një koment te karta dhe ekipi zgjohet, bën punën dhe ta kthen me hapa që i ndjek edhe një njeri i lodhur.","f.tester.h":"Fillimisht kontrollon një testues AI","f.tester.p":"Para se të të vijë diçka, testuesi ndjek hapat në një kopje të aplikacionit dhe tregon çfarë pa, me një pamje ekrani. Shfletoji ato që kaluan dhe prano me një klik.","f.proof.h":"Prova, jo premtime","f.proof.p":"Çdo dorëzim tregon çfarë ndryshoi: skedarët, ndryshimet, pamjet e ekranit. S'ke nevojë të hapësh çdo aplikacion për të parë nëse u krye.","f.chat.h":"Bisedo me drejtuesit e tu","f.chat.p":"Një shirit si në Discord: një ikonë për projekt, diamante vjollcë për atë që të do ty. Shkruaji drejtuesit një ide; ai e kthen në karta dhe plan, me një buton ✅ Shko.","f.tidy.h":"E mban vetë rendin","f.tidy.p":"Kartat e ngjashme bashkohen, titujt e ngatërruar rregullohen dhe një kontroll tokenësh e mban kodin të hollë. Më pak gjëra për të ndërruar, më pak për të menduar.","f.private.h":"I yti, në kompjuterin tënd","f.private.li1":"Tabela punon në kompjuterin tënd dhe i përgjigjet vetëm ty.","f.private.li2":"Mesazhet private mes njerëzve janë të enkriptuara nga skaji në skaj.","f.private.li3":"Pa llogari, pa gjurmues, pa cookies.","f.lang.h":"Në gjuhën tënde","f.lang.p":"Mbi 120 gjuhë, nga holandishtja, uellsishtja dhe japonishtja te piratët, Yoda dhe klingonishtja, me kalim të shpejtë në anglisht për termat profesionalë.","f.service.h":"Nga një ide te një shërbim i vërtetë","f.service.p":"Ndërtove diçka me AI që njerëzit tani e përdorin? Shënoje si shërbim dhe tabela të ndihmon ta mbash mirë: kontrolle funksionimi, një faqe publike statusi, incidente me analizë, ndryshime që kanë nevojë për një Go, kopje rezervë të kontrolluara çdo ditë. Ndihma të mëson çdo hap ndërsa ecën.","msgr.h2":"AI-gile Messenger: ekipi yt në xhep","msgr.p1":"Fol me ekipin tënd AI pa hapur tabelën. Bisedo me drejtuesit e projekteve dhe me miqtë, shiko hapat e testimit të një karte dhe përgjigju, të gjitha nga telefoni.","msgr.p2":"Për ta lidhur, skano një kod QR në tabelën tënde. Herën e parë? Një bisedë demo miqësore të tregon si funksionon.","msgr.when":"Fillimisht Android, pastaj një version web për telefona dhe iPhone.","msgr.who":"Drejtuesi yt i projektit","msgr.b1":"Rregullimi i modalitetit të errët është gati. Do hapat e testimit?","msgr.b2":"Po, të lutem!","msgr.b3":"1. Hap Cilësimet. 2. Zgjidh I errët. Duket mirë?","tl.aria":"Kronologjia nga biseda e parë te plani","tl.h2":"Nga biseda e parë te ajo që vjen më pas","tl.lede":"Data dhe orë të vërteta, në zonën tënde kohore. Pas sot është plan, pa data të premtuara.","tl.today":"Sot","tl.planned":"e planifikuar","tl.doing":"në punë","tl.cards.one":"{n} kartë","tl.cards.other":"{n} karta","join.h2":"Bashkohu","join.lede":"AI-gile po ndërtohet nga një tip i çuditshëm me mjekër, me AuDHD dhe disa beteja me shëndetin mendor, dhe nga shumë agjentë të durueshëm. Tani për tani është private, në alfa të mbyllur me miq. Do ta provosh kur të hapet?","join.btn":"Shpreh interes","join.small":"Do të shkruajmë me email, asgjë tjetër","footer.tag":"AI-gile. Pa gjurmues, pa cookies, pa kafe mbledhjeje.","footer.licence":"Licenca e biznesit","footer.status":"Gjendja","footer.privacy":"Çfarë ruajmë","footer.thanks":"Thirrjet falë ChilledChat","form.sending":"Po dërgohet…","form.failed":"Nuk funksionoi: provo përsëri më vonë.","form.offline":"Nuk u arrit AI-gile: provo përsëri më vonë.","form.keep":"E përdorim vetëm për të të kthyer përgjigje, pastaj e fshijmë. Pa gjurmues, pa cookies.","form.keepLink":"Çfarë ruajmë","interest.title":"AI-gile: më njofto kur hapet alfa","interest.description":"Lër emailin për të mësuar kur hapet alfa ose beta e mbyllur e AI-gile.","interest.h1":"🔔 Më njofto kur hapet","interest.lede":"AI-gile është në para-alfa të mbyllur. Lër emailin dhe do të të shkruajmë një herë, kur të ketë vend për ty.","interest.email":"Emaili yt","interest.which":"Cili test?","interest.alpha":"Alfa e mbyllur: e hershme, e ashpër, plot ndryshime","interest.beta":"Beta: më e qëndrueshme, më vonë","interest.both":"Cilado, cila të vijë e para","interest.submit":"Më shto në listë","interest.thanks":"Faleminderit! Je në listë.","licence.title":"AI-gile: licenca e biznesit","licence.description":"E përdor AI-gile në biznesin tënd? Apliko për një licencë biznesi falas.","licence.h1":"📜 Licenca e biznesit","licence.lede":"E përdor AI-gile në punë? Na trego kush je dhe çfarë bën. Nëse sjell diçka të mirë, licenca është falas.","licence.company":"Kompania","licence.website":"Faqja e internetit","licence.what":"Çfarë bën","licence.how":"Si ndihmon botën","licence.email":"Emaili","licence.submit":"Apliko","licence.thanks":"Faleminderit! Do të përgjigjemi me email.","status.title":"Gjendja e AI-gile","status.h1":"Gjendja e AI-gile","status.quiet":"Gjithçka e qetë","status.intro":"A po funksionon AI-gile tani? Kjo faqe kontrollon çdo 5 minuta faqen e internetit, ndarjen e tabelave, thirrjet dhe shkarkimin.","status.up":"Funksionon (u përgjigj për {ms} ms)","status.slow":"Nuk u përgjigj në kontrollin e fundit, po provoj përsëri","status.down":"Nuk funksionon: nuk u përgjigj në dy kontrollet e fundit","status.svc.web":"Faqja e internetit","status.svc.web.offers":"Kjo faqe: çfarë është AI-gile dhe formulari i interesit","status.svc.boards":"Ndarja e tabelave","status.svc.boards.offers":"Tabela publike, mesazhe mes miqve dhe ftesa","status.svc.calls":"Thirrjet","status.svc.calls.offers":"Zë, video dhe ndarje ekrani në AI-gile","status.svc.download":"Shkarkimi","status.svc.download.offers":"Instaluesi për Windows dhe lidhjet e ftesave","status.checking":"Po kontrollohet…","status.offline":"Shërbimi i gjendjes nuk arrihet tani (po provoj përsëri)","status.updated":"përditësuar {ago}","status.justNow":"tani fill","status.min":"{n} min më parë","status.hours":"{n} orë më parë","status.days":"{n} ditë më parë","privacy.title":"AI-gile: çfarë ruajmë","privacy.h1":"Çfarë ruajmë","privacy.lede":"Shkurt: vetëm atë që na dërgon, dhe jo për shumë kohë.","privacy.only":"Vetëm atë që na dërgon: atë që shkruan në një formular, si emailin tënd. Asgjë tjetër për ty.","privacy.sealed":"Vuloset që serveri ynë të mos e lexojë dot: në shfletuesin tënd para se të niset (në një shfletues më të vjetër, sapo mbërrin). Vetëm tabela jonë mund ta hapë.","privacy.server":"Fshihet nga serveri sapo arrin në tabelën tonë. Çdo gjë që mbetet aty pas 30 ditësh fshihet gjithsesi.","privacy.board":"E mbajmë në tabelën tonë vetëm derisa të të përgjigjemi, pastaj e fshijmë edhe aty.","privacy.none":"Pa gjurmues, pa cookies, pa analitikë.","privacy.local":"Gjuha jote dhe zgjedhja mes temës së çelët dhe të errët mbeten në shfletuesin tënd. Nuk na dërgohen kurrë.","privacy.ask":"Do që të zhduket më herët? Përgjigju emailit tonë dhe na e thuaj.","live.h2":"Shikoje duke u ndërtuar, drejtpërdrejt","live.caption":"Çdo kartë është e fshehur: sheh formën e punës, jo fjalët.","live.watching.one":"drejtpërdrejt: {n} po shikon","live.watching.other":"drejtpërdrejt: {n} po shikojnë","live.last.now":"Karta e fundit u zhvendos pak më parë","live.last.min.one":"Karta e fundit u zhvendos {n} minutë më parë","live.last.min.other":"Karta e fundit u zhvendos {n} minuta më parë","live.last.hour.one":"Karta e fundit u zhvendos {n} orë më parë","live.last.hour.other":"Karta e fundit u zhvendos {n} orë më parë","live.last.day.one":"Karta e fundit u zhvendos {n} ditë më parë","live.last.day.other":"Karta e fundit u zhvendos {n} ditë më parë","live.offline":"Tabela drejtpërdrejt po merr pak pushim. Kthehu së shpejti.","live.cols":"Backlog|Për t'u bërë|Në punë|Ekipi po kontrollon|Për ty ta testosh|Për ekipin|Kryer","footer.models":"AI-gile ekzekuton modele IA për ty. Ç'thonë dhe ç'bëjnë ato është e tyre, ndaj kontrolloje para se t'i besosh.","privacy.ai.h":"Pjesa e IA-së","privacy.ai.models":"AI-gile është tabela. Punën e bëjnë modele IA të kompanive të tjera, si Claude, Codex dhe Gemini, në llogaritë e tua.","privacy.ai.check":"Ç'shkruajnë dhe ç'bëjnë vjen prej tyre dhe mund të jetë gabim. Kontrolloje para se të mbështetesh te ajo ose ta publikosh.","privacy.ai.files":"Ato ndryshojnë skedarë dhe ekzekutojnë komanda në dosjet që lidh. Mbaj një kopje rezervë.","privacy.ai.send":"Ç'i jep një modeli shkon te kompania që e drejton, sipas kushteve të saj. Zbatohen kushtet dhe kostot e secilës.","privacy.ai.asis":"AI-gile është një version i hershëm provë, i dhënë ashtu siç është."},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robotë.","Deleguar."]},{"n":2,"texts":["Kanban robotësh.","Agjentët punojnë.","Idetë ndërtohen."]},{"n":3,"texts":["Kanban për robotë.","Idetë bëhen funksione.","Kanban falas agjentësh."]},{"n":5,"texts":["Tabelë kanban e drejtuar nga agjentë.","Ti shkruan karta. Agjentët ndërtojnë.","Falas, lokale, testuar, pak çudi."]},{"n":8,"texts":["Një tabelë kanban falas ku punojnë agjentë AI.","Shkruaj një ide. Agjentët e ndërtojnë. Ti e pranon.","Agjilitet për një njeri dhe shumë robotë të durueshëm."]},{"n":13,"texts":["Një tabelë kanban në kompjuterin tënd ku kartat i marrin agjentët AI e punojnë.","Shkruaj një ide. Një ekip agjentësh e ndërton. Një testues e kontrollon. Ti thua po.","Falas, pa llogari e pa gjurmues: një tabelë, disa robotë dhe ti ke fjalën."]},{"n":21,"texts":["AI-gile është një tabelë kanban për të punuar me agjentë AI që programojnë. Ata marrin kartat; ti i teston dhe i pranon.","Çdo projekt ka një drejtues dhe një ekip agjentësh AI. Shkruaj koment te çdo kartë dhe ekipi nis punën.","Një tabelë personale detyrash, falas, që punon në kompjuterin tënd. Punëtorët janë robotë. Ai që thotë po je ti."]},{"n":34,"texts":["Ti vë idetë në tabelë. Një ekip agjentësh AI i kthen në funksione që punojnë, i teston dhe ta kthen me hapa për t'i provuar. Asgjë nuk quhet e kryer derisa ta thuash ti.","AI-gile është një tabelë kanban e bërë në shtëpi, që Rich e ndërtoi me shumë ndihmë nga agjentët që tani i drejton vetë. Është falas, punon në kompjuterin tënd dhe ndahet me miqtë, nuk shitet.","Imagjino një tabelë kanban të zakonshme, me kolona nga Backlog te Kryer, vetëm se kartat i marrin agjentë AI. Raportojnë përparimin, pyesin kur ngecin dhe gjithmonë presin miratimin tënd."]},{"n":55,"texts":["AI-gile është një tabelë kanban ku ekipi përbëhet nga agjentë AI. Çdo projekt ka një drejtues që planifikon punën dhe ndihmës që e ndërtojnë. Kur një funksion është gati, një testues AI e provon dhe merr një pamje ekrani, pastaj ai bie në grumbullin tënd. Pranoje, ose shkruaj koment dhe ata e ripunojnë.","Nisi si mënyra e një njeriu për të ndjekur shumë seanca programimi me AI njëkohësisht, dhe u rrit në një tabelë të vërtetë. Punon në kompjuterin tënd, nuk kërkon llogari dhe nuk ka gjurmues. Është falas për miqtë dhe të kureshtarët. Është edhe e papërfunduar, ndaj prit skaje të ashpra dhe ndonjë befasi.","Ja versioni i sinqertë. Idetë duhet t'i kesh prapë ti, dhe rezultatet duhet t'i kontrollosh prapë ti. AI-gile bën gjithçka në mes: i mban kartat në rregull, zgjon agjentin e duhur kur komenton, tregon saktësisht çfarë ndryshoi dhe i vë të gjitha në një grumbull të shkurtër për ty."]},{"n":89,"texts":["AI-gile është një tabelë kanban falas që e ekzekuton në kompjuterin tënd. Në vend të njerëzve, çdo projekt ka një ekip agjentësh AI: një drejtues që idetë e tua i kthen në karta dhe plan, dhe ndihmës që i marrin kartat sipas përparësisë. Kur diçka është ndërtuar, një testues AI ndjek hapat e testit dhe të tregon çfarë pa. Pastaj pret në një grumbull me emrin Për ty. Ti e pranon, ose komenton dhe ekipi provon përsëri. Asgjë nuk arrin te Kryer pa ty.","Disa gjëra që mund të mos i presësh. Një roje nate e mbush kolonën Për t'u bërë ndërsa ti fle, duke zgjedhur karta që nuk kanë nevojë për përgjigje nga ti. Një numërues tokenësh tregon sa kanë përdorur agjentët sot dhe këtë javë, dhe Modaliteti pa tokenë u thotë të ndalojnë shpenzimin. Mund t'u shkruash miqve, dhe mesazhet private janë të enkriptuara nga skaji në skaj. Tabela flet rreth 120 gjuhë, përfshirë holandisht, flamandisht, piratësh dhe klingonisht. Asgjë nga kjo nuk kushton asnjë qindarkë, dhe askush nuk po përpiqet të ta shesë.","AI-gile është një projekt i vogël personal, jo kompani. Rich donte të kujdesej për disa projekte programimi me AI pa hapur çdo aplikacion për t'i kontrolluar, ndaj ai dhe agjentët ndërtuan një tabelë për këtë, pastaj me të ndërtuan pjesën tjetër të saj. Është në para-alfa të mbyllur, që do të thotë se punon, më së shumti, për një grusht miqsh. Nuk ka faqe çmimesh, buletin dhe as plan rritjeje. Nëse të duket e dobishme, mund të kërkosh ta provosh kur të hapet pak më shumë."]},{"n":144,"texts":["AI-gile është një tabelë kanban për një njeri dhe shumë agjentë AI. Punon në kompjuterin tënd dhe është plotësisht falas. Shton projekte dhe secili merr një drejtues dhe një ekip të vogël. Bisedon me drejtuesin, pak si në Discord, dhe përshkruan një ide; drejtuesi e kthen në karta dhe plan, pastaj pret që ti të shtypësh Shko. Ekipi i kalon kartat sipas përparësisë, me një rresht komandash të thjeshtë të bërë për modelet gjuhësore. Para se diçka të të kthehet, një testues AI ndjek hapat në një kopje të aplikacionit dhe bashkëngjit një pamje ekrani. Puna e përfunduar bie në grumbullin tënd me skedarët e ndryshuar dhe ndryshimet. Ti e pranon, ose lë një koment dhe ekipi zgjohet e provon përsëri. Vetëm ti mund ta kalosh një kartë te Kryer.","Një ditë me AI-gile, përafërsisht. Në mbrëmje lë disa komente: ky buton është në vendin e gabuar, ajo listë duhet renditur, mund të kemi një temë të errët. Shkon të flesh. Agjentët i lexojnë komentet, bëjnë ndryshimet, i testojnë dhe ta kthejnë punën. Nëse Për t'u bërë mbaron, roja e natës e mbush nga backlog me karta që nuk kanë nevojë për përgjigje nga ti. Në mëngjes ka një grumbull të shkurtër: disa pyetje dhe disa gjëra për t'u provuar, secila me hapa që i ndjek edhe një njeri i përgjumur dhe me një pamje ekrani që punon. I kalon një nga një, pranon të mirat dhe kthen të tjerat. Numëruesi i tokenëve tregon sa shpenzoi gjithçka, dhe Modaliteti pa tokenë është për javët e pakta. Pastaj ha mëngjes, ku agjentët ende nuk mund të ndihmojnë.","Së pari, çfarë nuk është AI-gile. Nuk është startup, nuk shitet dhe askush nuk mbledh të dhënat e tua. Është një tabelë falas që punon në kompjuterin tënd, pa llogari, pa gjurmues dhe pa cookies. Çfarë është: një vend i rregullt për të parë të gjitha projektet e programimit me AI njëherësh, me një ekip agjentësh që bëjnë kartat dhe ti që merr vendimet. Bashkon kartat e ngjashme, rregullon titujt e ngatërruar dhe vëzhgon që kodi të mbetet i hollë. Flet rreth 120 gjuhë, nga holandishtja dhe flamandishtja te piratët dhe klingonishtja. Miqtë mund t'i shkruajnë njëri-tjetrit privatisht dhe të enkriptuar. E ndërtoi Rich me një numër të madh agjentësh të durueshëm, kryesisht duke përdorur vetveten. Është në para-alfa të mbyllur, ndaj në disa vende është e ashpër. Nëse të tingëllon argëtuese, kërko me mirësi dhe mund të hysh herët."]}],"quips":{"1":"Një fjalë. E guximshme. Ndoshta tepër.","3":"Tri fjalë. Tashmë më të sinqerta se shumica e faqeve të produkteve.","8":"Tetë fjalë. Prapë më të shkurtra se një mbledhje e shkurtër.","21":"Gjatësitë janë story points, meqë ra fjala. Natyrisht që janë.","55":"Pesëdhjetë e pesë fjalë. Dy karta u kryen ndërsa lexoje.","144":"Kjo është e gjata. Nuk ka 233. Agjentët kanë shkuar të flenë."}},"timeline":{"first-idea.name":"Ideja e parë","first-idea.line":"Biseda e parë, para se të ekzistonte ndonjë kod.","first-board.name":"Tabela e parë","first-board.line":"Një tabelë që ndjek ndërtimin e vet: karta, kolona, tërhiq e lësho, projekte.","team-roles.name":"Ekipi dhe rolet","team-roles.line":"Profile agjentësh, shabllone ekipesh, hapësira dhe kush bën çfarë.","install.name":"Instalimi dhe versionet","install.line":"Një zip që e instalon edhe një mik, vetëpërditësime, kanale dhe kthim prapa.","usage-saver.name":"Kursimi i përdorimit","usage-saver.line":"Mat sa kushtojnë ekzekutimet, mbaje kodin të hollë, kurse kufirin tënd.","friends.name":"Miqtë dhe ndarja","friends.line":"Mesazhe private, një rele e kodifikuar, ftesa, role dhe projekte të përbashkëta.","languages.name":"Gjuhët","languages.line":"Çdo tekst ekrani në një skedar gjuhe, me holandishten dhe flamandishten të parat.","ai-tester.name":"Testuesi AI","ai-tester.line":"Një testues kontrollon çdo dorëzim i pari dhe tregon çfarë pa.","website.name":"Faqja e internetit","website.line":"aigile.lol, parapamja dhe kjo kronologji.","streaming.name":"Biseda dhe transmetimi","streaming.line":"Discord, Twitch, OBS, modaliteti i transmetuesit, GIF-e dhe emoji.","no-ai.name":"Edicioni pa AI","no-ai.line":"Një tabelë për njerëzit që programojnë pa AI, dhe tabela publike.","night-watch.name":"Roja e natës","night-watch.line":"Një rojtar dhe Scrum Master i mbajnë ekipet në punë ndërsa ti fle.","p-more.name":"Gjithçka tjetër","p-more.line":"Ide më të vogla që presin radhën.","p-android.name":"Telefoni dhe Android","p-android.line":"Arrije tabelën nga telefoni, pastaj një aplikacion Android vendas.","p-release.name":"Alfa e më tej","p-release.line":"Alfa e mbyllur, faqja e gjallë, pastaj beta.","p-languages.name":"Më shumë gjuhë","p-languages.line":"130 gjuhë dhe një mënyrë zhytjeje për ata që mësojnë.","p-engines.name":"Më shumë motorë AI","p-engines.line":"Zgjidh Claude, Codex, Gemini, Copilot ose Cursor për çdo agjent.","p-pro.name":"Praktikë profesionale","p-pro.line":"Etiketa rreziku, porta bashkimi, karta incidentesh dhe parapete.","p-self.name":"Kujdesi për ty","p-self.line":"Modaliteti i lodhjes, kujtesa për kujdesin ndaj vetes dhe 4:20.","p-servers.name":"Serverët dhe rritja","p-servers.line":"Cilësime globale serveri, role dhe planifikim për rritje.","p-livestream.name":"Shtesa transmetimi","p-livestream.line":"Biseda e Twitch, emoji të personalizuara dhe një pamje e gjallë publike."},"words":{"button":"📖 Termat profesionalë","h":"📖 Fjalët e shpjeguara","intro":"Trajnim falas me fjalë të thjeshta: çdo fjalë që has nga një ide e parë deri te një shërbim mbi të cilin mbështeten njerëzit, me Agile, ndërtimin, sigurinë dhe punën me AI gjatë rrugës.","search":"Kërko një fjalë…","none":"Asnjë fjalë nuk përputhet.","close":"Mbyll","count":{"one":"{count} fjalë","other":"{count} fjalë"},"groups":[{"id":"idea","name":"💡 Ideja dhe zbulimi"},{"id":"plan","name":"🗺️ Planifikimi i punës"},{"id":"agile","name":"🔁 Mënyrat e punës Agile"},{"id":"build","name":"🛠️ Ndërtimi"},{"id":"test","name":"🧪 Testimi dhe cilësia"},{"id":"change","name":"🔀 Ndryshime pa rrezik"},{"id":"run","name":"🛎️ Mbajtja e një shërbimi"},{"id":"sec","name":"🔒 Siguria dhe privatësia"},{"id":"ai","name":"🤖 Puna me AI"},{"id":"money","name":"💰 Paratë dhe licencat"}],"list":[{"id":"discovery","g":"idea","word":"Zbulimi (Discovery)","text":"Faza e hershme kur zbulon cili problem ia vlen të zgjidhet dhe për kë, përpara se të ndërtohet gjë.","also":["discovery","faza e zbulimit","zbulim","discovery phase"]},{"id":"problemstmt","g":"idea","word":"Përcaktimi i problemit","text":"Një ose dy fjali që thonë kush ka një problem, çfarë është dhe pse ka rëndësi, që të gjithë të synojnë të njëjtën gjë.","also":["përshkrimi i problemit","problem statement","problem statements"]},{"id":"user","g":"idea","word":"Përdorues","text":"Një person që përdor atë që ndërton ti. Puna bëhet për nevojat e përdoruesve.","also":["përdoruesi","përdoruesit","user","users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Palë e interesuar","text":"Kushdo që interesohet si del puna ose preket prej saj, si ata që e paguajnë, e përdorin ose e mbështesin.","also":["pala e interesuar","palët e interesuara","stakeholder","stakeholders"]},{"id":"persona","g":"idea","word":"Persona","text":"Një person i shpikur por realist që përfaqëson një lloj përdoruesi, që ekipi të pyesë “a do ta gjente Sami këtë të lehtë?”","also":["personas","personat"]},{"id":"userresearch","g":"idea","word":"Kërkim mbi përdoruesit","text":"Të flasësh me njerëz të vërtetë dhe t'i vëzhgosh për të mësuar çfarë u duhet, në vend që të hamendësosh.","also":["intervista me përdoruesit","user research","user interviews","kërkimi mbi përdoruesit"]},{"id":"journey","g":"idea","word":"Udhëtimi i përdoruesit","text":"Hapat që ndërmerr një person për të bërë diçka, nga dëgjimi i parë deri në fund, edhe jashtë produktit tënd. Kur e vizaton, shihet ku ngecin.","also":["user journey","user journeys","customer journey","udhëtimi i klientit","udhëtimet e përdoruesve"]},{"id":"painpoint","g":"idea","word":"Pikë dhimbjeje (pain point)","text":"Diçka që i bezdis ose i ngadalëson njerëzit sot. Produktet e mira i heqin pikat e dhimbjes.","also":["pain point","pain points","pikë dhimbjeje","pikat e dhimbjes"]},{"id":"assumption","g":"idea","word":"Supozim","text":"Diçka që e beson por që s'e ke kontrolluar ende. Kur i shkruan supozimet, shihet çfarë duhet provuar së pari.","also":["supozime","supozimi","supozimet","assumption","assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Hipotezë","text":"Një hamendje e mirë që planifikon ta kontrollosh, me atë që pret të ndodhë, si “njerëzit do të regjistrohen nëse muaji i parë është falas”.","also":["hipoteza","hipotezat","hypothesis","hypotheses"]},{"id":"experiment","g":"idea","word":"Eksperiment","text":"Një provë e vogël e planifikuar për të mësuar nëse një ide funksionon, përpara se të vësh shumë mbi të.","also":["eksperimente","eksperimenti","eksperimentet","experiment","experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Prova e konceptit (PoC)","text":"Një provë e shpejtë dhe e papërpunuar për të parë nëse një ide mund të funksionojë fare. Zakonisht hidhet tutje sapo ke përgjigjen.","also":["PoC","proof of concept","prova e konceptit"]},{"id":"prototype","g":"idea","word":"Prototip","text":"Një model i hershëm i produktit, shpesh me imazhe që klikohen, për ta provuar idenë te njerëzit përpara se ta ndërtosh siç duhet.","also":["prototipe","prototipi","prototipet","prototype","prototypes"]},{"id":"wireframe","g":"idea","word":"Wireframe","text":"Një skicë e thjeshtë e një ekrani që tregon ku vendoset çdo gjë, pa ngjyra e pa përmbajtje të vërtetë.","also":["wireframes","skicë ekrani","skica e ekranit"]},{"id":"mockup","g":"idea","word":"Mockup","text":"Një pamje e detajuar se si do të duket një ekran, me ngjyra dhe tekst të vërtetë, por ende asgjë nuk funksionon.","also":["mockups","mock-up","mock-ups","makete","maketi"]},{"id":"bizcase","g":"idea","word":"Arsyetimi i biznesit (business case)","text":"Arsyet pse bëhet një projekt: sa kushton, çfarë sjell ose kursen dhe cilat janë rreziqet.","also":["business case","business cases","arsyetimi i biznesit"]},{"id":"feasibility","g":"idea","word":"Realizueshmëria","text":"A mund të ndërtohet dhe të mirëmbahet vërtet diçka me kohën, paratë dhe aftësitë që ke.","also":["feasibility","i realizueshëm","fizibiliteti"]},{"id":"outcome","g":"idea","word":"Rezultati (outcome)","text":"Ndryshimi që do për njerëzit, si më pak takime të humbura. Ka më shumë rëndësi se sasia e asaj që ndërton.","also":["outcome","outcomes","rezultati","rezultate"],"noTip":1},{"id":"output","g":"idea","word":"Prodhimi (output)","text":"Diçka që e bën ekipi, si një ekran i ri ose një raport. Ta bësh nuk do të thotë vetvetiu se i ndihmon dikujt.","also":["output","outputs","prodhimi","prodhime"],"noTip":1},{"id":"successmetric","g":"idea","word":"Matësi i suksesit","text":"Një numër që tregon nëse puna bëri atë për të cilën ishte, si më shumë njerëz që e mbarojnë porosinë.","also":["success metric","success metrics","metrika e suksesit","matësit e suksesit"]},{"id":"kpi","g":"idea","word":"Treguesi kyç i performancës (KPI)","text":"Një numër i rëndësishëm që e ndjek për të parë nëse gjërat shkojnë mirë, si regjistrimet në javë.","also":["KPI","KPIs","key performance indicator","treguesi kyç i performancës"]},{"id":"okr","g":"idea","word":"Objektivat dhe rezultatet kyç (OKR)","text":"Një mënyrë për të vënë qëllime: objektivi thotë çfarë dëshiron, dhe disa rezultate kyç janë numrat që tregojnë se e arrite.","also":["OKR","OKRs","objektivat dhe rezultatet kyç"]},{"id":"product","g":"plan","word":"Produkt","text":"Ajo që ndërtohet dhe mirëmbahet për përdoruesit e saj, si një aplikacion, një faqe interneti ose një mjet.","also":["produkte","produkti","produktet","produktit","product","products"],"noTip":1},{"id":"vision","g":"plan","word":"Vizioni i produktit","text":"Një deklaratë e shkurtër për kë e ndihmon produkti dhe ku po shkon në afat të gjatë.","also":["vizioni","vision statement","product vision","deklarata e vizionit"]},{"id":"po","g":"plan","word":"Pronari i produktit (PO)","text":"Personi që vendos çfarë ndërtohet dhe në çfarë radhe, që ekipi të punojë gjithmonë në atë që ka më shumë rëndësi. Në AI-gile ky je ti.","also":["PO","product owner","product owners","pronari i produktit"]},{"id":"pm","g":"plan","word":"Menaxheri i produktit (PM)","text":"Personi që kujdeset për drejtimin e produktit: cilat probleme zgjidh, për kë dhe pse. PM mund të nënkuptojë edhe menaxher projekti, ndaj kontrollo cilin.","also":["PM","product manager","product managers","menaxheri i produktit"]},{"id":"projmgr","g":"plan","word":"Menaxheri i projektit","text":"Personi që e mban një projekt në kohë dhe brenda buxhetit, duke ndjekur kush bën çfarë dhe deri kur.","also":["project manager","project managers","menaxher projekti","menaxheri i projektit"]},{"id":"roadmap","g":"plan","word":"Udhërrëfyes (roadmap)","text":"Një plan i përafërt i asaj që vjen në muajt e ardhshëm, me radhë. Tregon drejtimin, jo datat e sakta, dhe ndryshon ndërsa mëson.","also":["roadmap","roadmaps","udhërrëfyesi","udhërrëfyes"]},{"id":"milestone","g":"plan","word":"Pikë referimi (milestone)","text":"Një pikë në projekt që ia vlen të shënohet, si “versioni i parë live” ose “100 përdorues”.","also":["milestone","milestones","pika referimi","pikë referimi"]},{"id":"mvp","g":"plan","word":"Produkti minimal i zbatueshëm (MVP)","text":"Versioni më i vogël i një produkti që është ende i dobishëm për njerëz të vërtetë, që të mësosh prej tyre herët.","also":["MVP","MVPs","minimum viable product","produkti minimal i zbatueshëm"]},{"id":"requirement","g":"plan","word":"Kërkesë","text":"Diçka që produkti i përfunduar duhet të bëjë ose të jetë.","also":["kërkesa","kërkesat","kërkesës","requirement","requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Fusha e punës (scope)","text":"Çfarë përfshihet në punë dhe, njësoj e rëndësishme, çfarë nuk përfshihet.","also":["scope","in scope","out of scope","brenda fushës","jashtë fushës","fusha e punës"]},{"id":"scopecreep","g":"plan","word":"Zgjerimi i fushës së punës (scope creep)","text":"Kur puna ngarkohet pak e nga pak me gjëra të reja, pa u pajtuar njeri për kohën ose koston shtesë, dhe kështu nuk mbaron kurrë.","also":["scope creep","feature creep","zgjerimi i fushës"]},{"id":"feature","g":"plan","word":"Veçori (feature)","text":"Një gjë që produkti mund të bëjë për njerëzit, si “rivendos fjalëkalimin”.","also":["feature","features","veçori","veçoria","veçoritë"],"noTip":1},{"id":"epic","g":"plan","word":"Epic","text":"Një punë e madhe, shumë e gjerë për një herë, ndaj ndahet në karta më të vogla.","also":["epics","epik","epikë"]},{"id":"story","g":"plan","word":"Histori përdoruesi (user story)","text":"Një punë e vogël e shkruar nga ana e përdoruesit: “Si blerës, dua ta ruaj shportën, që ta mbaroj më vonë.” Hap një bisedë për çfarë do të ndërtohet.","also":["user story","user stories","histori përdoruesi","historia e përdoruesit","historitë e përdoruesve"]},{"id":"ac","g":"plan","word":"Kriteret e pranimit (AC)","text":"Kontrollet që duhet të kalojë një kartë për t'u quajtur e kryer, të rënë dakord para se të fillojë puna, si “shporta është ende aty pasi dal dhe hyj përsëri”.","also":["AC","acceptance criteria","kriteret e pranimit"]},{"id":"task","g":"plan","word":"Detyrë","text":"Një punë e vetme për t'u bërë, shpesh një hap i vogël i një historie më të madhe.","also":["detyra","detyrat","detyrës","task","tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Ticket","text":"Një fjalë tjetër për kartën: një copë pune ose një kërkesë, e ndjekur nga fillimi deri në fund.","also":["tickets","tiketë","tiketa"]},{"id":"priority","g":"plan","word":"Përparësi","text":"Sa e rëndësishme ose urgjente është diçka krahasuar me gjithë të tjerat, që puna më e rëndësishme të bëhet e para.","also":["përparësitë","prioritet","prioritete","priority","priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Vënia e përparësive","text":"Renditja e punës sipas rëndësisë. Një mënyrë e zakonshme është MoSCoW: Must have (duhet), Should have (do të duhej), Could have (mund ta kemi), Won’t have this time (jo këtë herë).","also":["prioritizim","prioritizimi","prioritizoj","MoSCoW"]},{"id":"estimate","g":"plan","word":"Vlerësim","text":"Një hamendje e mirë se sa e madhe ose sa e gjatë është një punë. Është hamendje, jo premtim.","also":["vlerësime","vlerësimi","vlerësimet","estimate","estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Story points","text":"Një mënyrë për të hamendësuar madhësinë e punës duke krahasuar kartat mes tyre (“afërsisht dy herë më e madhe se ajo”) në vend të orëve. Nuk janë për të krahasuar ekipet.","also":["story point","pikë historie","pikët e historisë"]},{"id":"tshirt","g":"plan","word":"Madhësitë e bluzave (T-shirt sizing)","text":"Hamendja e madhësisë së punës si S, M, L ose XL. E shpejtë dhe e mjaftueshme për planifikimin e hershëm.","also":["t-shirt sizes","t-shirt sizing","madhësi bluzash"]},{"id":"poker","g":"plan","word":"Planning poker","text":"Një lojë për të vlerësuar: të gjithë tregojnë një kartë madhësie në të njëjtën kohë, pastaj ata me kartën më të lartë dhe më të ulët shpjegojnë pse.","also":["Scrum poker","poker planifikimi"]},{"id":"dependency","g":"plan","word":"Varësi","text":"Kur një punë nuk mund të fillojë ose të mbarojë derisa të bëhet një tjetër.","also":["varësia","varësitë","dependency","dependencies"]},{"id":"blocker","g":"plan","word":"Bllokues","text":"Çdo gjë që e ndalon punën të ecë përpara tani, si një përgjigje që mungon ose një mjet i prishur.","also":["bllokuesi","bllokuesit","blocker","blockers"]},{"id":"deadline","g":"plan","word":"Afati","text":"Data deri në të cilën duhet të mbarojë diçka.","also":["afat","afatet","deadline","deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Dorëzimi (deliverable)","text":"Diçka konkrete që puna e prodhon dhe e dorëzon, si një faqe që funksionon ose një raport.","also":["deliverable","deliverables","dorëzim","dorëzimet"]},{"id":"forecast","g":"plan","word":"Parashikim","text":"Një parashikim i asaj që ka gjasa të ndodhë, si kur do të mbarojë puna, bazuar në atë që di deri tani.","also":["parashikime","parashikimi","parashikimet","forecast","forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Metrikë","text":"Çdo gjë që e mat dhe e ndjek me kalimin e kohës, si vizitat e faqes ose sa zgjat një rregullim.","also":["metrika","metrikat","metrikës","metric","metrics"]},{"id":"feedback","g":"plan","word":"Përshtypjet (feedback)","text":"Ajo që të thonë njerëzit për punën tënde, të mirë e të keqe. Ta marrësh herët dhe shpesh është zemra e Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Lista e pritjes e ideve dhe punës që nuk janë planifikuar ende, me më të rëndësishmen në krye. Asgjë aty nuk punohet derisa të kalojë te Për t'u bërë."},{"id":"sprint","g":"agile","word":"Sprint","text":"Një periudhë e shkurtër e caktuar pune (shpesh një ose dy javë, kurrë më shumë se një muaj) me një qëllim dhe një set kartash të dakordësuara për t'u mbaruar.","also":["sprint-et","sprinti","sprinte","sprints"]},{"id":"standup","g":"agile","word":"Stand-up","text":"Një takim i shpejtë ditor: çfarë bëri secili anëtar i ekipit, çfarë bën më pas dhe çfarë e pengon. Në Scrum quhet scrum ditor.","also":["standup","stand-ups","daily scrum","daily stand-up","scrum ditor"]},{"id":"kanban","g":"agile","word":"Kanban","text":"Një mënyrë pune ku kartat lëvizin nëpër kolonat e një tabele (si Për t'u bërë, Në punë, Kryer) dhe ekipi kufizon sa gjëra janë në punë njëherësh, që puna të rrjedhë."},{"id":"wip","g":"agile","word":"Kufiri WIP","text":"WIP është shkurtim për work in progress, pra punë në vazhdim. Kufiri WIP është numri më i madh i kartave që duhet të mbajë një kolonë njëherësh, që ekipi t'i mbarojë gjërat para se të nisë të tjera.","also":["WIP"]},{"id":"dod","g":"agile","word":"Përkufizimi i Përfunduar","text":"Lista e shkurtër e ekipit për çfarë do të thotë “mbaruar”, si i testuar dhe i shpjeguar, para se një kartë të të dorëzohet. Binjaku i saj, Përkufizimi i Gati, thotë kur një kartë është mjaft e qartë për të filluar.","also":["Definition of Ready","DoD","DoR","përkufizimi i gatishmërisë"]},{"id":"retro","g":"agile","word":"Retro","text":"Një vështrim i rregullt prapa se si punon ekipi, për të rënë dakord për një ose dy gjëra që do t'i bëjë më mirë herën tjetër. Shkurtim për retrospektivë. Në AI-gile një retro propozon një ndryshim në mënyrat e punës së ekipit, dhe ti thua Go ose Jo ende.","also":["retrospektivë","retrospektiva"]},{"id":"swarm","g":"agile","word":"Tufa","text":"Të gjithë në punë: shumë njerëz lënë punët e tjera për të rregulluar bashkë një gjë urgjente derisa të zgjidhet. Në AI-gile çdo ekip ndihmon në një projekt, dhe projektet e tjera presin ndërkohë.","also":["swarm","swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"Në Scrum, personi që e ndihmon ekipin të punojë mirë: heq çfarë i bllokon, i mban mbledhjet në rrugë të drejtë dhe nxit zakone të mira, pa urdhëruar askënd. Në AI-gile Lead Scrum Master zbulon kartat e ngecura, u jep shtysë ekipeve dhe të kujton çfarë po pret, në çdo projekt.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"Një mënyrë pune me hapa të vegjël: ndërton pak, tregon shpesh rezultate të vërteta, mëson nga ajo që thonë njerëzit dhe e ndryshon planin ndërsa ecën, në vend që të planifikosh gjithçka paraprakisht.","also":["Agile development","agile ways of working","zhvillim agile","mënyra agile e punës"]},{"id":"manifesto","g":"agile","word":"Manifesti Agile","text":"Një deklaratë e shkurtër e shkruar në 2001 nga krijues softueri. Vë njerëzit, rezultatet që funksionojnë, punën e ngushtë me klientët dhe përgjigjen ndaj ndryshimit përpara planeve të rënda dhe burokracisë.","also":["Agile Manifesto","Manifesto for Agile Software Development","manifesti agile"]},{"id":"waterfall","g":"agile","word":"Waterfall","text":"Mënyra më e vjetër e punës: planifikon gjithçka, pastaj e ndërton të gjithën, pastaj e teston të gjithën, një fazë pas tjetrës. Ndryshimet vonë janë të vështira dhe të shtrenjta.","also":["waterfall model","modeli waterfall","modeli ujëvarë"]},{"id":"iteration","g":"agile","word":"Iteracion","text":"Një cikël ku ndërton diçka, e kontrollon dhe e përmirëson. Puna Agile është një varg ciklesh të tilla, dhe sprinti është një lloj i tyre.","also":["iteracione","iteracioni","iteracionet","iteration","iterations"]},{"id":"increment","g":"agile","word":"Inkrement","text":"Një pjesë e re që funksionon, shtuar te produkti në një sprint ose raund pune, dhe që përshtatet me atë që ishte aty më parë.","also":["inkremente","inkrementi","inkrementet","increment","increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"Një mënyrë e njohur pune Agile: një ekip i vogël punon në sprinte të shkurtra drejt një qëllimi, me role të caktuara dhe pak mbledhje të rregullta për të planifikuar, kontrolluar dhe përmirësuar."},{"id":"scrumteam","g":"agile","word":"Ekipi Scrum","text":"Grupi i vogël që e bën punën në Scrum: një pronar produkti, një Scrum Master dhe zhvilluesit.","also":["Scrum team","Scrum teams","ekipi scrum","ekipet scrum"]},{"id":"ceremonies","g":"agile","word":"Ngjarjet Scrum","text":"Mbledhjet e rregullta në Scrum: planifikimi i sprintit, scrum-i ditor, rishikimi i sprintit dhe retro. Shumë njerëz i quajnë ceremoni.","also":["ceremonies","Scrum ceremonies","ceremoni","ceremonitë","Scrum events"]},{"id":"sprintplan","g":"agile","word":"Planifikimi i sprintit","text":"Mbledhja në fillim të një sprinti ku ekipi bie dakord pse ka rëndësi sprinti, cilat karta merr përsipër dhe si nis.","also":["sprint planning","planning meeting","mbledhja e planifikimit"]},{"id":"sprintgoal","g":"agile","word":"Qëllimi i sprintit","text":"Një fjali që thotë për çfarë shërben një sprint. Detyrat e vogla mund të ndryshojnë gjatë rrugës, për sa kohë qëllimi arrihet.","also":["sprint goal","sprint goals","qëllimi i sprintit"]},{"id":"sprintbacklog","g":"agile","word":"Sprint backlog","text":"Kartat e zgjedhura për sprintin aktual, me planin e ekipit për t'i bërë.","also":["sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"Product backlog","text":"Lista e plotë e renditur e gjithçkaje që mund të ndërtohet për produktin, me më të rëndësishmen në krye. Ndryshon vazhdimisht ndërsa mëson.","also":["product backlogs"]},{"id":"productgoal","g":"agile","word":"Qëllimi i produktit","text":"Rezultati më i madh drejt të cilit punon produkti, që e ndihmon ekipin të zgjedhë çfarë të bëjë më pas.","also":["product goal","product goals","qëllimi i produktit"]},{"id":"refinement","g":"agile","word":"Rafinimi i backlog-ut","text":"Kalimi i rregullt nëpër backlog për të rregulluar, ndarë, renditur dhe shtuar detaje te kartat, që të jenë gati për t'u marrë. Quhet edhe backlog grooming.","also":["backlog grooming","refinement","backlog refinement","rafinim","grooming"]},{"id":"sprintreview","g":"agile","word":"Rishikimi i sprintit","text":"Një mbledhje në fund të sprintit ku ekipi tregon çfarë ka mbaruar dhe dëgjon çfarë mendojnë njerëzit, për të vendosur çfarë vjen më pas.","also":["sprint review","sprint reviews","rishikim sprinti"]},{"id":"demo","g":"agile","word":"Demo","text":"Të tregosh punën e mbaruar duke funksionuar, live, para njerëzve që e kanë kërkuar.","also":["demos","demonstrim","demonstrimi"],"noTip":1},{"id":"timebox","g":"agile","word":"Timebox","text":"Një sasi e caktuar kohe për diçka. Kur mbaron, ndalon, edhe nëse jo gjithçka është bërë.","also":["timeboxed","timeboxes","kuti kohe"]},{"id":"velocity","g":"agile","word":"Shpejtësia (velocity)","text":"Sa punë mbaron zakonisht një ekip në një sprint, e përdorur për të planifikuar sa të marrë herën tjetër. Nuk është notë për sa shumë mundohen njerëzit.","also":["velocity","team velocity","shpejtësia e ekipit"]},{"id":"capacity","g":"agile","word":"Kapaciteti","text":"Sa punë mund të marrë përsipër ekipi në një periudhë, pas pushimeve dhe punëve të tjera.","noTip":1},{"id":"burndown","g":"agile","word":"Grafiku burndown","text":"Një grafik i punës së mbetur në një sprint që zbret ditë pas dite. Nëse vija mbetet e sheshtë, diçka ka ngecur.","also":["burndown","burn-down chart","burndown chart","grafik burndown"]},{"id":"burnup","g":"agile","word":"Grafiku burnup","text":"Një grafik i punës së mbaruar që ngjitet me kohën, pranë totalit të planifikuar, që të shohësh kur do të arrish.","also":["burnup","burn-up chart","burnup chart","grafik burnup"]},{"id":"kanbanboard","g":"agile","word":"Tabela Kanban","text":"Vetë tabela: një kolonë për çdo fazë të punës, me karta që lëvizin nëpër të.","also":["Kanban board","Kanban boards","tabelë kanban"]},{"id":"pullsys","g":"agile","word":"Sistem tërheqjeje (pull)","text":"Një mënyrë pune ku puna e re nis vetëm kur dikush ka vend ta marrë, në vend që t'i vihet mbi një pjatë të mbushur.","also":["pull system","pull-based","sistemi pull"]},{"id":"flow","g":"agile","word":"Rrjedha (flow)","text":"Sa lehtë lëviz puna nëpër tabelë. Rrjedhë e mirë do të thotë që kartat vazhdojnë të lëvizin dhe nuk grumbullohen.","also":["flow","flow of work","rrjedha e punës"],"noTip":1},{"id":"leadtime","g":"agile","word":"Lead time","text":"Sa kohë kalon nga momenti kur dikush kërkon diçka deri kur ajo mbaron.","also":["lead times"]},{"id":"cycletime","g":"agile","word":"Cycle time","text":"Sa kohë i duhet një karte nga momenti kur nis vërtet puna mbi të deri kur mbaron.","also":["cycle times","koha e ciklit"]},{"id":"throughput","g":"agile","word":"Throughput","text":"Sa karta mbarohen në një javë, ose në çdo kohë të caktuar.","also":["throughput rate"]},{"id":"bottleneck","g":"agile","word":"Qafa e shishes (bottleneck)","text":"Faza e vetme ku puna grumbullohet dhe ngadalëson gjithçka pas saj, si qafa e ngushtë e një shishe.","also":["bottleneck","bottlenecks","qafa e shishes","fyti i shishes"]},{"id":"swimlane","g":"agile","word":"Swimlane","text":"Një rresht nëpër tabelë që grupon karta të një lloji, si puna urgjente ose kartat e një ekipi.","also":["swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean","text":"Një mënyrë pune që heq shpërdorimin (çdo gjë që nuk i ndihmon klientit) dhe e mban punën në lëvizje."},{"id":"waste","g":"agile","word":"Shpërdorim (waste)","text":"Në Lean, çdo gjë që kërkon përpjekje por nuk i ndihmon klientit, si pritja, ripunimi ose ndërtimi i gjërave që s'i përdor njeri.","noTip":1},{"id":"kaizen","g":"agile","word":"Përmirësim i vazhdueshëm","text":"Të bëhesh pak më mirë gjatë gjithë kohës me ndryshime të vogla e të rregullta, pastaj të kontrollosh nëse ndihmuan. Retro-t janë një mënyrë për ta bërë. Quhet edhe kaizen.","also":["kaizen","përmirësimi i vazhdueshëm","continuous improvement"]},{"id":"selforg","g":"agile","word":"Ekip vetëorganizues","text":"Një ekip që vendos vetë si ta bëjë punën, në vend që t'i thuhet hap pas hapi.","also":["self-organising","self-managing team","ekip vetëorganizues","vetëorganizim"]},{"id":"crossfunc","g":"agile","word":"Ekip ndërfunksional","text":"Një ekip që ka të gjitha aftësitë që i duhen për ta mbaruar punën vetë, si dizajnin, ndërtimin dhe testimin.","also":["cross-functional","cross-functional team","ekip ndërfunksional"]},{"id":"spike","g":"agile","word":"Spike","text":"Një kërkim i shkurtër me kohë të caktuar për t'iu përgjigjur një pyetjeje përpara se të angazhohesh në punën e vërtetë.","also":["spikes"]},{"id":"rework","g":"agile","word":"Ripunim","text":"Puna që bëhet sërish sepse nuk ishte e saktë herën e parë.","also":["ripunimi","rework","reworked","ripunoj"]},{"id":"safe","g":"agile","word":"Agile në shkallë (SAFe)","text":"Mënyra për të përdorur Agile nëpër shumë ekipe në një organizatë të madhe. SAFe (Scaled Agile Framework) është një shembull i njohur.","also":["scaled Agile","agile në shkallë"]},{"id":"repo","g":"build","word":"Repo","text":"Dosja e kodit të projektit me historikun e plotë të commit-eve. Mund të jetë në kompjuterin tënd, në GitHub, ose në të dyja vendet.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Një linjë pune e ndarë në kod, që ndryshimet të bëhen pa prekur versionin kryesor.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Një pamje e ruajtur e kodit, me një shënim të shkurtër për çfarë ndryshoi. Mund të kthehesh gjithmonë te njëra.","also":["commits","commit-e","commit-eve"]},{"id":"push","g":"build","word":"Push","text":"Dërgimi i pamjeve të ruajtura (commit-e) nga ky kompjuter te kopja e përbashkët online, si GitHub, që të kenë kopje rezervë dhe t'i marrin edhe të tjerët."},{"id":"merge","g":"build","word":"Merge","text":"Bashkimi i ndryshimeve nga një branch në një tjetër, zakonisht përsëri te versioni kryesor."},{"id":"pr","g":"build","word":"Pull request","text":"Kërkesa që ndryshimet e një branch-i të kontrollohen dhe të bashkohen te versioni kryesor. Disa faqe e quajnë merge request.","also":["PR","PRs","merge request"]},{"id":"refactor","g":"build","word":"Refactor","text":"Rregullimi i kodit pa ndryshuar çfarë bën: skedarë më të vegjël, emra më të qartë, më pak përsëritje."},{"id":"bug","g":"build","word":"Bug","text":"Diçka që nuk funksionon siç duhet.","also":["bugs","bug-e","bug-u","bug-et"]},{"id":"peerreview","g":"build","word":"Rishikim nga kolegët","text":"Një palë sy e dytë: dikush tjetër përveç autorit kontrollon punën para se të arrijë te ti, që të kalojnë më pak gabime. Në AI-gile një AI tjetër kontrollon çdo kartë.","also":["peer review","rishikim kodi","code review"]},{"id":"code","g":"build","word":"Kod","text":"Udhëzimet e shkruara që i thonë një kompjuteri çfarë të bëjë. Quhet edhe kod burimor.","also":["kodi","kodin","kodit","source code","kodi burimor","code"],"noTip":1},{"id":"proglang","g":"build","word":"Gjuhë programimi","text":"Një gjuhë për të shkruar kod, si JavaScript, Python ose Java. Gjuhë të ndryshme u përshtaten punëve të ndryshme.","also":["gjuha e programimit","gjuhët e programimit","programming language","programming languages"]},{"id":"developer","g":"build","word":"Zhvillues (dev)","text":"Dikush që shkruan dhe ndryshon kod. Quhet edhe programues ose inxhinier softueri.","also":["zhvillues","zhvilluesi","zhvilluesit","programues","programuesi","developer","developers","programmer","programmers","software engineer"]},{"id":"software","g":"build","word":"Softuer","text":"Programet që punojnë në kompjuterë e telefona, ndryshe nga vetë pajisjet (hardueri).","noTip":1},{"id":"app","g":"build","word":"Aplikacion (app)","text":"Shkurtim për aplikacion: një program që njerëzit e përdorin për të bërë diçka, në telefon, në kompjuter ose në shfletues.","also":["aplikacion","aplikacioni","aplikacionet","aplikacionit","app","apps","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"Aplikacion uebi (web app)","text":"Një aplikacion që punon në shfletues, ndaj nuk ka asgjë për të instaluar.","also":["web app","web apps","web application","aplikacion uebi","aplikacion në ueb"]},{"id":"frontend","g":"build","word":"Front end","text":"Pjesa e aplikacionit që e sheh dhe e klikon: ekranet, butonat dhe fjalët, shpesh në shfletuesin tënd.","also":["front-end","frontend","pjesa e përparme"]},{"id":"backend","g":"build","word":"Back end","text":"Pjesa e fshehur e aplikacionit që mban të dhënat dhe bën punën kur klikon diçka, si kontrollimi i fjalëkalimit tënd.","also":["back-end","backend","pjesa e pasme"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Të punosh edhe në pjesën e përparme, edhe në atë të pasme.","also":["full-stack"]},{"id":"ui","g":"build","word":"Ndërfaqja e përdoruesit (UI)","text":"Ajo që një person sheh dhe përdor në ekran: faqosja, butonat, menutë dhe teksti.","also":["UI","user interface","ndërfaqe","ndërfaqja"]},{"id":"ux","g":"build","word":"Përvoja e përdoruesit (UX)","text":"Si duket përdorimi i diçkaje: i lehtë, i qartë dhe i këndshëm, apo i ngatërruar dhe i ngadaltë.","also":["UX","user experience","përvoja e përdoruesit"]},{"id":"accessibility","g":"build","word":"Aksesueshmëria (a11y)","text":"Të bësh gjërat të përdorshme për të gjithë, përfshirë ata që nuk shohin mirë, nuk mund të përdorin miun ose përdorin lexues ekrani.","also":["a11y","accessibility","aksesueshmëri","qasshmëria","qasshmëri"]},{"id":"responsive","g":"build","word":"Dizajn responsiv","text":"Të bësh faqet të përshtaten dhe të punojnë mirë në çdo madhësi ekrani, nga telefoni te monitori i madh.","also":["responsive design","dizajn i përshtatshëm"]},{"id":"designsys","g":"build","word":"Sistem dizajni","text":"Një set i përbashkët ngjyrash, shkronjash, butonash dhe rregullash, që çdo ekran të duket dhe të sillet njësoj.","also":["design system","design systems","sistemi i dizajnit"]},{"id":"architecture","g":"build","word":"Arkitektura","text":"Forma e përgjithshme e një sistemi: cilat janë pjesët kryesore dhe si flasin me njëra-tjetrën."},{"id":"database","g":"build","word":"Bazë të dhënash (DB)","text":"Një depo e organizuar informacioni, si një fletë llogaritjeje shumë e fuqishme që aplikacioni mund ta lexojë dhe ta ndryshojë.","also":["baza e të dhënave","baza të dhënash","database","databases","DB"]},{"id":"schema","g":"build","word":"Skema e bazës së të dhënave","text":"Struktura e një baze të dhënash: cilat tabela informacioni ka dhe çfarë hyn në secilën.","also":["schema","skema","database schema"]},{"id":"sql","g":"build","word":"SQL","text":"Shkurtim për gjuhën e strukturuar të pyetjeve: gjuha që përdoret te shumë baza të dhënash për të kërkuar informacion ose për ta ndryshuar.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Të dhëna","text":"Informacioni që mban një kompjuter, si emra, porosi ose cilësime.","also":["të dhënat","data","dataset","datasets"],"noTip":1},{"id":"server","g":"build","word":"Server","text":"Një kompjuter që është gjithmonë ndezur dhe u përgjigjet kërkesave të kompjuterëve të tjerë, si dërgimi i një faqeje interneti kur e vizitosh.","also":["servers","serveri","serverët","serverit"]},{"id":"client","g":"build","word":"Klient","text":"Ana që kërkon diçka, zakonisht shfletuesi ose aplikacioni yt, duke folur me një server. Në biznes do të thotë thjesht edhe klient, pra blerës.","also":["klienti","klientët","client","clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Shkurtim për ndërfaqen e programimit të aplikacioneve: një menu e caktuar kërkesash që një program mund t'i bëjë një tjetri, si të pyesësh një shërbim moti për parashikimin e sotëm.","also":["APIs","application programming interface"]},{"id":"endpoint","g":"build","word":"Endpoint","text":"Një zë në menunë e një API-je: një adresë interneti që një program mund ta thërrasë për të marrë ose dërguar diçka.","also":["endpoints","pika fundore"]},{"id":"integration","g":"build","word":"Integrim","text":"Lidhja e dy sistemeve që të punojnë së bashku, si dyqani yt që u dërgon porositë softuerit të llogarive.","also":["integrime","integrimi","integrimet","integration","integrations"]},{"id":"webhook","g":"build","word":"Webhook","text":"Një mesazh që një sistem ia dërgon vetë një tjetri në çastin kur ndodh diçka, si “pagesa u pranua”.","also":["webhooks"]},{"id":"library","g":"build","word":"Bibliotekë (library)","text":"Kod i gatshëm që e ka shkruar dikush tjetër dhe që mund ta ripërdorësh në vend që ta shkruash vetë.","also":["bibliotekë","biblioteka","bibliotekat","library","libraries"],"noTip":1},{"id":"framework","g":"build","word":"Framework","text":"Një strukturë e gatshme për ndërtimin e një aplikacioni, që përcakton në masë të madhe si organizohet kodi, si skeleti i një shtëpie që e plotëson ti.","also":["frameworks","kornizë","korniza"]},{"id":"sdk","g":"build","word":"Paketa e zhvillimit të softuerit (SDK)","text":"Një kuti me mjete, kod dhe shembuj për ndërtimin e softuerit për një platformë ose shërbim të caktuar.","also":["SDK","SDKs","software development kit"]},{"id":"softdep","g":"build","word":"Varësi softuerike","text":"Një bibliotekë ose mjet që i duhet kodit tënd për të punuar. Mbajtja e tyre e përditësuar ka rëndësi për sigurinë.","also":["software dependency","software dependencies","varësitë softuerike"]},{"id":"package","g":"build","word":"Paketë","text":"Një tufë kodi të gatshëm që mund ta instalosh dhe ta përdorësh në një projekt.","also":["paketa","paketat","package","packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Menaxher paketash","text":"Një mjet që merr dhe përditëson paketat nga të cilat varet kodi yt. npm është një i zakonshëm.","also":["menaxheri i paketave","package manager","package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"Mjeti më i përdorur për mbajtjen e historikut të ndryshimeve të kodit, si commit-e dhe branch-e."},{"id":"github","g":"build","word":"GitHub","text":"Një faqe interneti që i mban repo-t e Git online, që ekipet të ndajnë kodin, të rishikojnë ndryshimet dhe të ndjekin punën."},{"id":"vcs","g":"build","word":"Kontrolli i versioneve","text":"Mbajtja e një historiku të plotë të çdo ndryshimi në skedarë, që të shohësh kush ndryshoi çfarë dhe të kthehesh mbrapsht nëse duhet. Git e bën këtë.","also":["version control","source control","version control system","sistemi i kontrollit të versioneve"]},{"id":"clone","g":"build","word":"Clone","text":"Bërja e kopjes tënde të plotë të një repo-je, me historikun e saj, në kompjuterin tënd.","also":["cloned","cloning","klonoj","klonim"]},{"id":"pull","g":"build","word":"Pull","text":"Marrja e commit-eve më të fundit nga kopja e përbashkët (si GitHub) në kompjuterin tënd. E kundërta e push.","also":["git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Branch kryesor","text":"Versioni zyrtar i kodit nga i cili punojnë të gjithë, që shpesh quhet main ose master.","also":["main branch","master branch","dega kryesore"]},{"id":"conflict","g":"build","word":"Konflikt bashkimi (merge conflict)","text":"Kur dy ndryshime prekin të njëjtat rreshta në mënyra të ndryshme, ndaj kompjuteri nuk mund t'i bashkojë dhe një person duhet të zgjedhë.","also":["merge conflict","merge conflicts","konflikt bashkimi","konflikte bashkimi"]},{"id":"diff","g":"build","word":"Diff","text":"Një pamje që tregon saktësisht çfarë ndryshoi mes dy versioneve: rreshtat e shtuar dhe rreshtat e hequr.","also":["diffs"]},{"id":"fork","g":"build","word":"Fork","text":"Kopja jote e repo-s së dikujt tjetër, që mund ta ndryshosh pa prekur origjinalin.","also":["forks","forked"]},{"id":"script","g":"build","word":"Skript","text":"Një program i shkurtër që bën një punë vetë, si rregullimi i skedarëve ose nisja e aplikacionit.","also":["skripte","skripti","skriptet","script","scripts"],"noTip":1},{"id":"build","g":"build","word":"Build","text":"Kthimi i kodit në diçka të gatshme për t'u ekzekutuar, ose vetë rezultati i gatshëm për ekzekutim.","also":["builds"],"noTip":1},{"id":"compile","g":"build","word":"Kompilim","text":"Përkthimi i kodit që kanë shkruar njerëzit në një formë që kompjuteri mund ta ekzekutojë drejtpërdrejt.","also":["compile","compiler","kompilator","kompiloj"]},{"id":"cli","g":"build","word":"Rreshti i komandave (CLI)","text":"Një dritare teksti ku shkruan udhëzime për kompjuterin në vend që të klikosh. Quhet edhe terminal.","also":["command line","command-line","CLI","terminal","terminali","rreshti i komandave"]},{"id":"config","g":"build","word":"Konfigurimi (config)","text":"Cilësimet që kontrollojnë si sillet softueri, të mbajtura veçmas nga kodi që të ndryshohen lehtë.","also":["config","configuration","konfigurim"],"noTip":1},{"id":"envvar","g":"build","word":"Ndryshore mjedisi","text":"Një cilësim që i jepet një programi kur nis, shpesh për adresa ose fjalëkalime që të mos shkruhen brenda kodit.","also":["environment variable","environment variables","env var","ndryshorja e mjedisit"]},{"id":"debugging","g":"build","word":"Debugging","text":"Gjetja e shkakut pse diçka nuk punon dhe rregullimi i tij.","also":["debug","debugged","debugim","debugoj"]},{"id":"pairing","g":"build","word":"Programim në çift","text":"Dy njerëz (ose një njeri dhe një AI) që punojnë bashkë në të njëjtin kod, njëri shkruan dhe tjetri kontrollon.","also":["pair programming","pairing","programimi në çift"]},{"id":"docs","g":"build","word":"Dokumentacion (docs)","text":"Shpjegime të shkruara se si punon diçka ose si përdoret.","also":["dokumentacioni","dokumentacion","documentation","docs"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"Skedari i parë për t'u lexuar në një repo: çfarë është projekti dhe si ta vësh në punë.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Sistem i trashëguar (legacy)","text":"Një sistem më i vjetër që ende përdoret dhe është i vështirë për t'u ndryshuar, shpesh sepse pak njerëz e kuptojnë ende.","also":["legacy system","legacy systems","legacy code","sistem legacy","kod legacy"]},{"id":"techdebt","g":"build","word":"Borxh teknik","text":"Shkurtore që kursejnë kohë tani por i ngadalësojnë ndryshimet e mëvonshme, si një hua që mbledh kamatë. Një refactor e shlyen.","also":["borxhi teknik","technical debt","tech debt"]},{"id":"test","g":"test","word":"Test","text":"Një kontroll që diçka punon siç duhet. Disa teste i ekzekuton kompjuteri vetë sa herë ndryshon kodi; të tjera janë ti që e provon një kartë të mbaruar para se ta pranosh.","also":["testi","testit","testin","teste","testet","testeve","testim","testimi","testuar","testosh","testesh","tests"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Shkurtim për sigurimin e cilësisë: gjithçka që bëhet për t'u siguruar që puna është e saktë para se të dalë live. Në AI-gile kjo do të thotë kontrollet automatike: kur QA është e kuqe, diçka dështoi dhe nuk mund të dalë live derisa të rregullohet.","also":["kontroll cilësie","kontrollet e cilësisë","sigurimi i cilësisë"]},{"id":"testpile","g":"test","word":"Stiva e testeve","text":"Kartat e mbaruara që presin t'i provosh, njëra pas tjetrës. Prano njërën ose ktheje me një shënim, dhe vjen tjetra.","also":["stiva testesh"]},{"id":"autotest","g":"test","word":"Test automatik","text":"Një kontroll që kompjuteri e bën vetë sa herë ndryshon kodi, për të kapur gabimet herët.","also":["teste automatike","testi automatik","automated test","automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Test manual","text":"Një person që e provon punën me dorë për të parë nëse sillet siç duhet.","also":["teste manuale","testi manual","manual test","manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Test njësie (unit test)","text":"Një kontroll i vogël automatik i një pjese shumë të vogël kodi më vete.","also":["unit test","unit tests","teste njësie"]},{"id":"integtest","g":"test","word":"Test integrimi","text":"Një kontroll që disa pjesë punojnë siç duhet bashkë, jo vetëm një nga një.","also":["integration test","integration tests","teste integrimi"]},{"id":"endtoend","g":"test","word":"Test nga fillimi në fund (E2E)","text":"Një test që vepron si një përdorues i vërtetë nga fillimi në fund, si regjistrimi, blerja dhe pagesa.","also":["E2E","end-to-end test","end-to-end tests","test E2E"]},{"id":"uat","g":"test","word":"Testimi i pranimit nga përdoruesi (UAT)","text":"Ata që kërkuan punën e provojnë vetë dhe thonë nëse bën atë që u duhet. Lista e Testeve në AI-gile është versioni i saj.","also":["UAT","acceptance testing","testimi i pranimit"]},{"id":"regression","g":"test","word":"Regresion","text":"Diçka që më parë punonte por u prish pas një ndryshimi. Testet e regresionit kontrollojnë që gjërat e vjetra punojnë ende.","also":["regresioni","regresione","regression","regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"Test tymi (smoke test)","text":"Një kontroll shumë i shpejtë që gjërat kryesore punojnë fare, për shembull menjëherë pasi një ndryshim del live. Nëse dështon, ndalo dhe shiko.","also":["smoke test","smoke tests","test tymi"]},{"id":"exploratory","g":"test","word":"Testim eksplorues","text":"Ta provosh produktin lirshëm dhe ta ngacmosh në mënyra të ndryshme, për të gjetur probleme që kontrollet e planifikuara nuk do t'i kapnin.","also":["exploratory testing","exploratory test","exploratory tests","testimi eksplorues"]},{"id":"testcase","g":"test","word":"Rast testimi","text":"Një skenar i shkruar për t'u provuar: hapat dhe ajo që duhet të ndodhë.","also":["rasti i testimit","raste testimi","test case","test cases"]},{"id":"coverage","g":"test","word":"Mbulimi me teste","text":"Sa pjesë e kodit kontrollohet nga testet automatike. Më shumë zakonisht do të thotë më shumë siguri, por vetëm mbulimi i lartë nuk provon që punon mirë.","also":["test coverage","code coverage","mbulimi i kodit"]},{"id":"testdata","g":"test","word":"Të dhëna testimi","text":"Informacion shembull i shpikur që përdoret gjatë testimit, që të mos ekspozohen të dhënat private të ndonjë personi të vërtetë.","also":["test data","test fixtures","të dhënat e testimit"]},{"id":"edgecase","g":"test","word":"Rast kufitar (edge case)","text":"Një situatë e pazakontë në skaje, si një formular bosh ose një emër me apostrof, ku shpesh gjërat prishen.","also":["edge case","edge cases","raste kufitare","rast kufitar"]},{"id":"happypath","g":"test","word":"Rruga e lumtur (happy path)","text":"Rruga normale ku gjithçka shkon mirë. Testimi i mirë provon edhe rrugët jo të lumtura."},{"id":"perftest","g":"test","word":"Testimi i performancës","text":"Kontrollimi sa i shpejtë është diçka dhe sa mirë përballon ngarkesën.","also":["performance testing","performance test","performance tests","testi i performancës"]},{"id":"loadtest","g":"test","word":"Testimi i ngarkesës","text":"Kontrollimi si përballon një sistem kur shumë njerëz e përdorin njëkohësisht.","also":["load testing","load test","load tests","testi i ngarkesës"]},{"id":"sectest","g":"test","word":"Testimi i sigurisë","text":"Kërkimi i dobësive që mund t'i lejonin dikujt ta keqpërdorë një sistem ose të shohë atë që nuk duhet.","also":["security testing","security test","security tests","testi i sigurisë"]},{"id":"accesstest","g":"test","word":"Testimi i aksesueshmërisë","text":"Kontrollimi që njerëz me aftësi të ndryshme mund ta përdorin produktin, përfshirë me lexues ekrani ose vetëm me tastierë.","also":["accessibility testing","accessibility test","testi i aksesueshmërisë","testimi i qasshmërisë"]},{"id":"linting","g":"test","word":"Linting","text":"Një kontroll automatik që gjen gabime të mundshme dhe stil të çrregullt në kod, si një kontrollues drejtshkrimi për programet.","also":["linter","lint"]},{"id":"static","g":"test","word":"Analizë statike","text":"Kontrollimi i kodit për probleme duke e lexuar automatikisht, pa e ekzekutuar.","also":["static analysis","static code analysis","analiza statike"]},{"id":"flaky","g":"test","word":"Test i paqëndrueshëm (flaky)","text":"Një test që herë kalon e herë dështon pa arsye të qartë, ndaj nuk mund t'i besohet plotësisht.","also":["flaky test","flaky tests","teste të paqëndrueshme"]},{"id":"repro","g":"test","word":"Riprodhim (repro)","text":"Ta bësh një bug të ndodhë sërish me qëllim duke ndjekur të njëjtat hapa, që të studiohet dhe të rregullohet. Shkrimi i këtyre hapave është pjesa më e dobishme e një raporti bug-u.","also":["repro","reproduce","steps to reproduce","riprodhoj","hapat për ta riprodhuar"]},{"id":"severity","g":"test","word":"Ashpërsia (severity)","text":"Sa i keq është efekti i një problemi, nga një bezdi e vogël deri te ndalimi i gjithçkaje.","also":["severity","severity level","ashpërsia","niveli i ashpërsisë"]},{"id":"deploy","g":"change","word":"Deploy","text":"Kopjimi i një versioni të ri të softuerit në kompjuterët që e ekzekutojnë, si në një kopje testimi ose në shërbimin live."},{"id":"release","g":"change","word":"Publikim","text":"Një paketë me emër e punës së mbaruar që del live bashkë, me shënime të shkurtra për çfarë ndryshoi. 🚀 Publikimet i shkruajnë shënimet nga kartat e përfunduara.","also":["publikime","publikimet","release"]},{"id":"rollback","g":"change","word":"Kthim mbrapsht","text":"Kthimi te versioni i fundit që punonte kur një i ri shkakton telashe. Në AI-gile, Kthim mbrapsht i mbledh hapat e zhbërjes të shkruara te çdo ndryshim në një listë të vetme kontrolli.","also":["rollback","kthe mbrapsht","u kthye mbrapsht"]},{"id":"live","g":"change","word":"Live","text":"Versioni i vërtetë që përdorin njerëzit, ndryshe nga një kopje për të provuar gjëra. Zhvilluesit e quajnë edhe prodhim (production).","also":["prodhim","produksion","production"],"noTip":1},{"id":"change","g":"change","word":"Ndryshim","text":"Një ndryshim i planifikuar te diçka që njerëzit mbështeten, i shkruar më parë: çfarë, pse, rreziku, kur dhe si zhbëhet. Fillo një me 🔀 Ngrit një ndryshim.","also":["ndryshime","kërkesë ndryshimi","kërkesa ndryshimi"],"noTip":1},{"id":"risk","g":"change","word":"Rrezik","text":"Diçka që mund të shkojë keq, e vlerësuar sipas sa e mundshme është dhe sa keq do të ishte. ⚠️ Rreziqe i mban në një listë, pikët më të larta të parat, secili me një datë për ta parë sërish.","also":["rreziqe","regjistri i rreziqeve"]},{"id":"chgwin","g":"change","word":"Dritare ndryshimesh","text":"Oraret kur ndryshimet lejohen të dalin live, si një mbrëmje e qetë të martë. Jashtë dritares një kartë ndryshimi nuk mund të përfundohet, përveç kur është urgjencë.","also":["dritaret e ndryshimeve","change window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Një kontroll i fundit pak para se një ndryshim të dalë live: secili që duhet ta miratojë thotë Go ose No go. Vazhdon vetëm kur të gjithë thonë Go.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Miratim","text":"Pritja për një po para se të fillojë puna. Një kartë që hap një mik, ose një ndryshim, pret te ✅ Miratime derisa ta miratosh ose ta refuzosh.","also":["miratime","mirato"]},{"id":"quiettime","g":"change","word":"Orë qetësie","text":"Një periudhë kohe, si gjatë një transmetimi live, një demoje ose natën, kur asgjë nuk del live. Ekipet vazhdojnë të punojnë dhe të testojnë, por dalja live pret derisa të mbarojë. Gjetkë quhet change freeze.","also":["orët e qetësisë","ngrirje ndryshimesh","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"Një mënyrë pune ku ata që ndërtojnë softuerin dhe ata që e mbajnë në punë veprojnë si një ekip, me shumë automatizim, që ndryshimet të dalin live shpesh dhe në mënyrë të sigurt."},{"id":"cicd","g":"change","word":"CI/CD (integrim dhe dorëzim i vazhdueshëm)","text":"Ndryshimet e të gjithëve bashkohen shpesh në versionin kryesor dhe kontrollohen automatikisht çdo herë (integrim i vazhdueshëm), që softueri të jetë gjithmonë gati të dalë live me një shtypje butoni (dorëzim i vazhdueshëm).","also":["CI/CD","CI","CD","continuous integration","continuous delivery","integrim i vazhdueshëm","dorëzim i vazhdueshëm"]},{"id":"contdeploy","g":"change","word":"Deploy i vazhdueshëm (continuous deployment)","text":"Një hap më tej se dorëzimi i vazhdueshëm: çdo ndryshim që kalon kontrollet del live vetë, pa buton për të shtypur.","also":["continuous deployment","continuous deployments","deploy i vazhdueshëm","vendosja e vazhdueshme"]},{"id":"pipeline","g":"change","word":"Pipeline","text":"Seria automatike e hapave nëpër të cilët kalon një ndryshim rrugës për të dalë live, si build, test, pastaj deploy.","also":["pipelines"]},{"id":"environment","g":"change","word":"Mjedis","text":"Një kopje e veçantë e sistemit për një qëllim, si një për të ndërtuar, një për të testuar dhe ajo live.","also":["mjedisi","mjedise","mjediset","environment","environments"],"noTip":1},{"id":"devenv","g":"change","word":"Mjedis zhvillimi","text":"Kopja ku punon një zhvillues, shpesh në kompjuterin e vet, ku po të prishësh diçka nuk dëmtohet askush.","also":["mjedisi i zhvillimit","development environment","dev environment"]},{"id":"testenv","g":"change","word":"Mjedis testimi","text":"Një kopje e veçantë e sistemit që përdoret vetëm për testim, që shërbimi i vërtetë të mos preket.","also":["mjedisi i testimit","test environment","test environments"]},{"id":"staging","g":"change","word":"Staging","text":"Një kopje e fundit e ngritur saktësisht si live, për një kontroll përfundimtar para se një ndryshim të dalë live.","also":["staging environment","mjedis staging"]},{"id":"artifact","g":"change","word":"Artefakt ndërtimi (build artifact)","text":"Skedari ose paketa që prodhon një build, gati për t'u ruajtur, kontrolluar ose vënë live.","also":["build artifact","build artifacts","artefakt","artefakte"]},{"id":"hotfix","g":"change","word":"Hotfix","text":"Një rregullim urgjent që del live shpejt, jashtë planit normal, sepse diçka e rëndësishme është prishur.","also":["hotfixes","rregullim urgjent"]},{"id":"patch","g":"change","word":"Patch","text":"Një përditësim i vogël që rregullon një bug ose mbyll një vrimë sigurie. Zbatimi i shpejtë i patch-eve të sigurisë ka rëndësi.","also":["patches","security patch","security patches","arna sigurie"]},{"id":"version","g":"change","word":"Numri i versionit","text":"Një etiketë si 2.4.1 që tregon cilin version e ke. Shpesh numri i parë ndryshon për ndryshime të mëdha dhe i fundit për rregullime të vogla.","also":["numri i versionit","numrat e versioneve","version number","version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Shënimet e versionit","text":"Një listë e shkurtër e thjeshtë e asaj që ndryshoi në një publikim, për ata që e përdorin, me rregullimet dhe kufizimet e njohura. Quhet edhe changelog.","also":["shënime versioni","release notes","changelog","change log"]},{"id":"flag","g":"change","word":"Feature flag","text":"Një çelës ndezur-fikur për një veçori, që puna e re të dalë live e fshehur dhe të ndizet (ose të fiket përsëri) pa një publikim të ri.","also":["feature flags","feature toggle","feature toggles","çelës veçorie"]},{"id":"rollfwd","g":"change","word":"Kalim përpara (roll forward)","text":"Rregullimi i një publikimi të keq duke nxjerrë shpejt një version të ri e të korrigjuar, në vend që të kthehesh te i vjetri.","also":["roll forward","rolling forward","rolled forward","kalim përpara"]},{"id":"canary","g":"change","word":"Publikim kanarinë (canary)","text":"Ta nxjerrësh një ndryshim live fillimisht për një grup të vogël, dhe për të gjithë vetëm kur duket në rregull. Emri vjen nga kanarinat që minatorët i merrnin nën tokë si sinjal paralajmërues.","also":["canary release","canary releases","canary","publikim canary"]},{"id":"bluegreen","g":"change","word":"Deploy blue-green","text":"Mbajtja e dy kopjeve të sistemit live dhe kalimi i të gjithëve te kopja e re njëherësh, që të mund të kthehesh menjëherë te e vjetra nëse diçka shkon keq.","also":["blue-green","blue green deployment","blue-green deployment","deploy blue-green","vendosje blue-green"]},{"id":"zerodown","g":"change","word":"Deploy pa ndërprerje","text":"Nxjerrja live e një versioni të ri pa e ndalur kurrë shërbimin për përdoruesit.","also":["zero downtime","zero-downtime","zero-downtime deployment","deploy pa ndërprerje"]},{"id":"chgenable","g":"change","word":"Mundësimi i ndryshimeve (change enablement)","text":"Ndihma që ndryshimet të kenë sukses: peshimi i rrezikut, marrja e miratimit të duhur dhe zgjedhja e një kohe të mirë. Quhet edhe menaxhim i ndryshimeve.","also":["change enablement","change management","menaxhimi i ndryshimeve"]},{"id":"cab","g":"change","word":"Bordi këshillimor i ndryshimeve (CAB)","text":"Një grup që shqyrton ndryshimet e rëndësishme dhe bie dakord nëse dhe kur mund të vazhdojnë.","also":["CAB","change advisory board"]},{"id":"stdchange","g":"change","word":"Ndryshim standard","text":"Një ndryshim me rrezik të ulët që bëhet çdo herë në të njëjtën mënyrë të provuar, ndaj miratohet paraprakisht.","also":["ndryshime standarde","standard change","standard changes"]},{"id":"normchange","g":"change","word":"Ndryshim normal","text":"Një ndryshim që duhet kontrolluar dhe miratuar para se të vazhdojë.","also":["ndryshime normale","normal change","normal changes"]},{"id":"emergchange","g":"change","word":"Ndryshim urgjent","text":"Një ndryshim që duhet bërë menjëherë për të rregulluar ose parandaluar telashe serioze, prandaj edhe miratimi është më i shpejtë.","also":["ndryshime urgjente","emergency change","emergency changes"]},{"id":"automation","g":"change","word":"Automatizim","text":"Ta ngarkosh kompjuterin ta bëjë vetë një punë që përsëritet, që të bëhet më shpejt dhe njësoj çdo herë.","also":["automatizimi","automatizuar","automation","automated"],"noTip":1},{"id":"infra","g":"change","word":"Infrastrukturë","text":"Makinat, rrjetet dhe shërbimet mbi të cilat punon softueri.","also":["infrastruktura","infrastrukturën","infra"]},{"id":"iac","g":"change","word":"Infrastruktura si kod (IaC)","text":"Përshkrimi i serverëve dhe cilësimeve në skedarë që mbahen me kodin, që të rindërtohen saktësisht njësoj çdo herë.","also":["IaC","infrastructure as code","infrastruktura si kod"]},{"id":"cloud","g":"change","word":"Cloud (reja)","text":"Marrja me qira e kompjuterëve, ruajtjes dhe shërbimeve nga një ofrues i madh nëpërmjet internetit, në vend që t'i kesh vetë makinat.","also":["cloud","reja kompjuterike","the cloud","cloud computing"]},{"id":"provider","g":"change","word":"Ofrues cloud","text":"Një kompani që jep me qira fuqi llogaritëse nëpërmjet internetit, si Amazon Web Services (AWS), Microsoft Azure ose Google Cloud.","also":["ofruesi i cloud","cloud provider","cloud providers"]},{"id":"hosting","g":"change","word":"Hostimi","text":"Vendi ku jeton dhe punon aplikacioni ose faqja jote që njerëzit ta arrijnë, zakonisht marrë me qira nga një kompani.","also":["hosting","hostim","hostuar"]},{"id":"domain","g":"change","word":"Emri i domenit","text":"Adresa e internetit që shkruajnë njerëzit, si example.com. E merr me qira nga viti në vit, ndaj duhet rinovuar.","also":["domeni","domen","domain","domain name","domain names"]},{"id":"dns","g":"change","word":"DNS","text":"Shkurtim për sistemin e emrave të domeneve: libri i adresave të internetit, që e kthen një emër si example.com në adresën e kompjuterit të duhur.","also":["domain name system"]},{"id":"container","g":"change","word":"Kontejner","text":"Një paketë e mbyllur që mban një aplikacion dhe gjithçka që i duhet, që të punojë njësoj në çdo kompjuter. Docker është mjeti më i njohur.","also":["kontejnerë","kontejneri","container","containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Makinë virtuale (VM)","text":"Një kompjuter i simuluar që punon brenda një kompjuteri të vërtetë, që një makinë e madhe të sillet si shumë.","also":["VM","VMs","virtual machine","virtual machines","makina virtuale"]},{"id":"serverless","g":"change","word":"Serverless","text":"Ekzekutimi i kodit pa u kujdesur vetë për asnjë server: ofruesi e ekzekuton kur duhet dhe ti paguan për atë që përdor."},{"id":"lb","g":"change","word":"Ekuilibrues ngarkese (load balancer)","text":"Diçka që i shpërndan vizitorët mes disa serverëve, që asnjëri të mos mbingarkohet.","also":["load balancer","load balancers","ekuilibruesi i ngarkesës"]},{"id":"cache","g":"change","word":"Cache","text":"Një depo e shpejtë rezultatesh të fundit, e mbajtur afër, që e njëjta gjë të mos merret ose llogaritet sërish. Pastrimi i saj mund t'i rregullojë faqet që duken të vjetruara.","also":["caches","caching","cached","memorie e shpejtë"]},{"id":"cdn","g":"change","word":"Rrjeti i shpërndarjes së përmbajtjes (CDN)","text":"Një rrjet serverësh anembanë botës që mbajnë kopje të faqeve dhe fotove të tua pranë vizitorëve, që të ngarkohen shpejt.","also":["CDN","content delivery network"]},{"id":"migration","g":"change","word":"Migrim","text":"Zhvendosja e të dhënave ose sistemeve nga një konfigurim i vjetër në një të ri, ose ndryshimi i kujdesshëm i strukturës së një baze të dhënash.","also":["migrime","migrimi","migrimet","migration","migrations","database migration"]},{"id":"service","g":"run","word":"Shërbim","text":"Diçka që ke ndërtuar dhe që njerëzit e kanë të nevojshme, si një faqe interneti ose një aplikacion, që kujdesesh të vazhdojë të punojë. Shëno “Ky projekt është një shërbim” dhe shkruaj çfarë ofron, kush e përdor dhe kush është në gatishmëri.","also":["shërbime","shërbimi"]},{"id":"uptimepct","g":"run","word":"Uptime","text":"Sa nga koha një shërbim është në punë, zakonisht si përqindje. 99.9% lejon ende rreth 43 minuta jashtë pune në muaj.","also":["uptime percentage","përqindja e uptime"]},{"id":"uptime","g":"run","word":"Kontroll funksionimi","text":"Një kontroll automatik, çdo disa minuta, nëse shërbimi yt ende përgjigjet. Nëse dështon disa herë rresht, AI-gile hap vetë një kartë incidenti.","also":["uptime checks","kontrolle uptime"]},{"id":"statuspage","g":"run","word":"Faqja e statusit","text":"Një faqe publike që tregon nëse një shërbim punon (jeshile, portokalli ose e kuqe) me lajmin e fundit, që njerëzit që e përdorin ta shohin vetë në vend që të pyesin.","also":["faqe statusi","status page"]},{"id":"desk","g":"run","word":"Desku i shërbimit","text":"Vendi ku vijnë pyetjet dhe njoftimet nga njerëzit që përdorin shërbimin tënd. AI-gile e rendit secilin si kërkesë, incident ose ide, dhe të thotë kur duket si diçka e raportuar tashmë.","also":["desku","help desk","helpdesk","shërbimi i ndihmës"]},{"id":"svcrequest","g":"run","word":"Kërkesë shërbimi","text":"Kur dikush kërkon diçka të zakonshme, si një llogari të re ose pak ndihmë, në vend që të raportojë se diçka është prishur. Pret radhën e vet; incidenti shkon i pari.","also":["kërkesa shërbimi","kërkesë","kërkesa"]},{"id":"incident","g":"run","word":"Incident","text":"Diçka që është prishur ose nuk punon siç duhet për njerëzit që e përdorin tani, si faqja e internetit që nuk hapet ose është shumë e ngadaltë. Një kartë incidenti 🔥 kalon para radhës: ta vësh sërish në punë vjen e para.","also":["incidente","incidentet","ndërprerje"]},{"id":"major","g":"run","word":"Incident i madh","text":"Një incident i madh: shumë njerëz të prekur, ose para a të dhëna në rrezik. Një buton i vë të gjitha ekipet mbi të (tufa), zgjon atë që është në gatishmëri dhe kërkon një përditësim statusi çdo 30 minuta.","also":["incidente të mëdha","major incident"]},{"id":"oncall","g":"run","word":"Në gatishmëri","text":"Të jesh ai që përgjigjet kur diçka prishet, edhe natën. Çdo shërbim ka një anëtar ekipi në gatishmëri që zgjohet i pari për incidentet e tij.","also":["gatishmëri","on call","on-call"]},{"id":"replyby","g":"run","word":"Koha e përgjigjes","text":"Sa gjatë mund të presë një kartë për përgjigjen e parë, për shembull një orë për një incident. Pas kësaj merr një orë të kuqe, që asgjë të mos harrohet në heshtje. Quhet edhe objektiv përgjigjeje.","also":["kohët e përgjigjes","objektiv përgjigjeje"]},{"id":"postmortem","g":"run","word":"Analiza pas incidentit","text":"Një vështrim i shkurtër pas një incidenti: çfarë ndodhi, çfarë ndihmoi dhe çfarë duhet ndryshuar, pa fajësuar askënd. Një incident nuk mbyllet pa të. Shpesh quhet edhe post-mortem.","also":["analiza pas incidenteve","post-mortem","postmortem"]},{"id":"problem","g":"run","word":"Problem","text":"Shkaku i fshehur pas një ose më shumë incidenteve. Një kartë 🧩 problemi bashkon incidentet që përsëriten, që shkaku të gjendet dhe të rregullohet përgjithmonë.","also":["probleme","problemet"],"noTip":1},{"id":"rootcause","g":"run","word":"Shkaku rrënjësor","text":"Arsyeja e vërtetë pse u prish diçka, jo vetëm ajo që pe të shkonte keq. Rregullo shkakun rrënjësor dhe incidenti nuk kthehet më.","also":["shkaqe rrënjësore","root cause"]},{"id":"workaround","g":"run","word":"Zgjidhje e përkohshme","text":"Një mënyrë për t'i mbajtur gjërat në punë derisa rregullimi i vërtetë të jetë gati, si rinisja e diçkaje kur ngec. Shkruhet në kartën e problemit që askush të mos ketë nevojë ta zbulojë sërish.","also":["zgjidhje të përkohshme","workaround"]},{"id":"knownerror","g":"run","word":"Gabim i njohur","text":"Një problem shkaku i të cilit kuptohet por ende nuk është rregulluar, zakonisht me një zgjidhje të përkohshme të shkruar. 🧩 Gabimet e njohura i liston, që të gjithë të përdorin zgjidhjen e përkohshme në vend që të gërmojnë sërish.","also":["gabime të njohura","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Udhëzime hap pas hapi për të rregulluar një lloj të njohur problemi, që të bëhet njësoj dhe shpejt çdo herë. Pas një incidenti të madh ekipi mund të të propozojë një për ta miratuar.","also":["runbook-e","udhëzues pune"]},{"id":"ci","g":"run","word":"Artikull konfigurimi","text":"Një gjë nga e cila varet shërbimi yt, si një server, një domen, një certifikatë, një çelës ose një furnizues. 🗂️ Artikujt e konfigurimit i rendit sipas shërbimit, që të shohësh se çfarë prek një incident dhe çfarë duhet rinovuar ose kopjuar.","also":["artikuj konfigurimi","artikujt e konfigurimit"]},{"id":"expiry","g":"run","word":"Data e skadimit","text":"Data kur diçka pushon së punuari nëse nuk rinovohet, si certifikata e sigurisë e një faqeje interneti ose adresa e saj. AI-gile i ndjek këto data dhe krijon një kartë për ta rinovuar secilën 30 ditë përpara, që asgjë të mos ndalojë befas.","also":["datat e skadimit","skadim","skadimi","mbikëqyrja e skadimit"]},{"id":"backup","g":"run","word":"Kopje rezervë","text":"Një kopje e ruajtur e të dhënave të tua nga më parë, për t'u mbështetur nëse diçka humbet ose dëmtohet. AI-gile bën një kopje rezervë të tabelave të tua çdo ditë.","also":["kopje rezervë","backup","bekap"]},{"id":"restore","g":"run","word":"Rikthim","text":"Kthimi i të dhënave nga një kopje rezervë. Një kopje rezervë vlen vërtet vetëm kur e di që mund të rikthehet, ndaj ia vlen ta provosh herë pas here.","also":["rikthe","u rikthye","restore","rivendosje"]},{"id":"svcreview","g":"run","word":"Rishikimi i shërbimit","text":"Një vështrim pas në një muaj të një shërbimi: incidentet e hapura dhe të rregulluara, sa shpejt morën përgjigje njerëzit, koha e funksionimit dhe tokenët e përdorur. Rishikimi mujor e tregon këtë për çdo shërbim.","also":["rishikime shërbimi","rishikimi mujor","rishikime mujore"]},{"id":"accessreview","g":"run","word":"Rishikimi i aksesit","text":"Kontrollimi çdo 90 ditë se kush mund të hyjë ende: lidhjet e ndara, rolet e miqve dhe fjalëkalimet e çelësat e ruajtur. I mban ose i heq secilin, që qasja e vjetër të mos mbetet.","also":["rishikime aksesi"]},{"id":"improvements","g":"run","word":"Lista e përmirësimeve","text":"Gjithçka që ekipi vendosi të bëjë më mirë, në një vend: sugjerimet nga retro, veprimet nga rishikimet dhe rregullimet e problemeve, secila me statusin e vet. E gjen te 📈 Përmirësimet.","also":["listat e përmirësimeve","përmirësime","përmirësimet"]},{"id":"tokencap","g":"run","word":"Kufiri i tokenëve","text":"Një kufi mujor për tokenët që mund të përdorin agjentët e një shërbimi. Në 80% merr një paralajmërim; në 100% puna e tyre në sfond pret deri muajin tjetër ose derisa ta rritësh kufirin.","also":["kufijtë e tokenëve","kufi tokenësh"]},{"id":"svcmgmt","g":"run","word":"Menaxhimi i shërbimeve","text":"Gjithçka që duhet për ta mbajtur një shërbim të dobishëm dhe në punë për ata që mbështeten tek ai, ditë pas dite.","also":["service management","menaxhim shërbimi"]},{"id":"itil","g":"run","word":"ITIL","text":"Një udhëzues shumë i përdorur për menaxhim të mirë shërbimesh, që mbulon gjëra si incidentet, problemet dhe ndryshimet. Emri dikur ishte shkurtim i IT Infrastructure Library."},{"id":"itsm","g":"run","word":"Menaxhimi i shërbimeve IT (ITSM)","text":"Drejtimi i teknologjisë si shërbim për njerëzit, me mënyra të qarta për të trajtuar kërkesat, incidentet, ndryshimet dhe përmirësimet.","also":["ITSM","IT service management"]},{"id":"managed","g":"run","word":"Shërbim i menaxhuar","text":"Një shërbim që e drejton dhe e mirëmban dikush tjetër për ty, sipas një marrëveshjeje se sa mirë duhet të punojë.","also":["shërbime të menaxhuara","managed service","managed services"]},{"id":"svcowner","g":"run","word":"Pronari i shërbimit","text":"Personi që përgjigjet për një shërbim në tërësi: sa mirë punon, sa kushton dhe si përmirësohet.","also":["service owner","service owners","pronarët e shërbimit"]},{"id":"sla","g":"run","word":"Marrëveshja e nivelit të shërbimit (SLA)","text":"Një premtim i shkruar për klientët se sa mirë do të punojë një shërbim, si “në punë 99.9% të kohës” ose “përgjigje brenda një ore”, shpesh me kthim parash nëse premtimi nuk mbahet.","also":["SLA","SLAs","service level agreement","marrëveshja e nivelit të shërbimit"]},{"id":"slo","g":"run","word":"Objektivi i nivelit të shërbimit (SLO)","text":"Synimi i vetë ekipit se sa mirë duhet të punojë një shërbim gjatë një periudhe, zakonisht pak më i rreptë se SLA për siguri.","also":["SLO","SLOs","service level objective"]},{"id":"sli","g":"run","word":"Treguesi i nivelit të shërbimit (SLI)","text":"Matja reale që krahasohet me një synim, si pjesa e vizitave që u ngarkuan mirë.","also":["SLI","SLIs","service level indicator"]},{"id":"availability","g":"run","word":"Disponueshmëria","text":"Nëse njerëzit mund ta përdorin një shërbim kur u duhet, shpesh matur si uptime.","also":["availability","high availability","disponueshmëri e lartë"]},{"id":"downtime","g":"run","word":"Downtime","text":"Koha kur një shërbim nuk punon ose është fikur, e planifikuar ose jo.","also":["down time","kohë jashtë pune"]},{"id":"errorbudget","g":"run","word":"Buxheti i gabimeve (error budget)","text":"Sasia e vogël dështimi që e lejon synimi yt i besueshmërisë. Sa kohë mbetet ende, mund të marrësh rreziqe me ndryshimet; kur mbaron, duhet të ngadalësosh.","also":["error budget","error budgets","buxheti i gabimeve"]},{"id":"outage","g":"run","word":"Ndërprerje (outage)","text":"Një kohë kur një shërbim është jashtë pune ose i prishur rëndë për përdoruesit.","also":["outage","outages","ndërprerje","ndërprerja"]},{"id":"degraded","g":"run","word":"Shërbim i degraduar","text":"Punon, por keq: ngadalë, ose me disa pjesë që nuk punojnë.","also":["degraded","degraded service","i degraduar"]},{"id":"monitoring","g":"run","word":"Monitorimi","text":"Vëzhgimi automatik i një shërbimi gjatë gjithë kohës, që problemet të zbulohen, mundësisht para se t'i vënë re përdoruesit.","also":["monitoring","monitorim"]},{"id":"observability","g":"run","word":"Vëzhgueshmëria (observability)","text":"Sa mirë mund të kuptosh çfarë ndodh brenda një sistemi nga jashtë, nga regjistrat (logs), numrat dhe gjurmët e tij.","also":["observability","o11y","vëzhgueshmëri"]},{"id":"log","g":"run","word":"Log (regjistër)","text":"Një ditar i vazhdueshëm që mban një program për atë që po bën, që përdoret për të kuptuar çfarë shkoi keq.","also":["log","logs","logging","regjistër","regjistri","regjistrat"],"noTip":1},{"id":"trace","g":"run","word":"Gjurmë (trace)","text":"Një regjistrim se si një kërkesë udhëton nëpër pjesët e ndryshme të një sistemi, hap pas hapi, duke treguar ku u ngadalësua.","also":["trace","traces","tracing","gjurmë","gjurma"]},{"id":"latency","g":"run","word":"Vonesa (latency)","text":"Sa kohë i duhet diçkaje të përgjigjet, si pritja mes klikimit dhe shfaqjes së faqes.","also":["latency"]},{"id":"alert","g":"run","word":"Alarm","text":"Një mesazh automatik që diçka ka nevojë për vëmendje, si faqja e internetit që nuk përgjigjet.","also":["alarme","alarmi","alert","alerts","alerting","njoftim urgjent"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Lodhja nga alarmet","text":"Kur ka kaq shumë alarme sa njerëzit fillojnë t'i injorojnë, përfshirë edhe ato të rëndësishme.","also":["alert fatigue","alarm fatigue","lodhja nga alarmet"]},{"id":"dashboard","g":"run","word":"Paneli i kontrollit (dashboard)","text":"Një ekran që tregon numrat dhe statuset më të rëndësishme me një shikim.","also":["dashboard","dashboards","paneli i kontrollit","panel kontrolli"],"noTip":1},{"id":"paging","g":"run","word":"Thirrje urgjente (paging)","text":"Thirrja ose zgjimi urgjent i personit në gatishmëri për një problem.","also":["paging","paged","thirrje urgjente"]},{"id":"escalation","g":"run","word":"Përshkallëzim (escalation)","text":"Thirrja e dikujt me më shumë aftësi ose autoritet kur një çështje nuk zgjidhet në nivelin aktual, ose jo mjaft shpejt.","also":["escalation","escalate","escalated","përshkallëzim","përshkallëzoj"]},{"id":"triage","g":"run","word":"Triazh (triage)","text":"Renditja e shpejtë e çështjeve që vijnë sipas urgjencës dhe rëndësisë, që më e rënda të trajtohet e para.","also":["triage","triaged","triazh"]},{"id":"impact","g":"run","word":"Ndikimi (impact)","text":"Sa ndikon diçka te njerëzit: sa shumë prej tyre dhe sa rëndë.","noTip":1},{"id":"urgency","g":"run","word":"Urgjenca","text":"Sa shpejt duhet trajtuar diçka. Ndikimi dhe urgjenca bashkë caktojnë përparësinë.","noTip":1},{"id":"plevels","g":"run","word":"Nivelet e përparësisë (P1, P2…)","text":"Etiketa për sa urgjente është një çështje. P1 është më e rënda dhe kërkon veprim menjëherë.","also":["P1","P2","P3","P4","nivelet e përparësisë"]},{"id":"queue","g":"run","word":"Radha e tiketave","text":"Lista e kërkesave dhe incidenteve që presin të merren.","also":["radha e tiketave","ticket queue","ticket queues"]},{"id":"tiers","g":"run","word":"Linja e parë dhe linja e dytë","text":"Nivelet e mbështetjes: linja e parë merr thirrjen dhe rregullon gjërat e thjeshta; linja e dytë ka aftësi më të thella për ato më të vështira. Quhen edhe tier 1 dhe tier 2.","also":["linja e parë","linja e dytë","first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Komandanti i incidentit","text":"Personi i vetëm që drejton përgjigjen ndaj një incidenti, që të gjithë të dinë kush vendos dhe kush bën çfarë.","also":["komandanti i incidentit","incident commander","incident commanders"]},{"id":"responsetime","g":"run","word":"Koha e përgjigjes","text":"Sa kohë kalon deri sa dikush merr për herë të parë një kërkesë ose incident.","also":["koha e përgjigjes","response time","response times"]},{"id":"resolution","g":"run","word":"Koha e zgjidhjes","text":"Sa kohë duhet për ta zgjidhur plotësisht një kërkesë ose incident, nga raportimi deri te rregullimi.","also":["koha e zgjidhjes","resolution time","resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Koha mesatare e rikuperimit (MTTR)","text":"Mesatarisht, sa kohë duhet për ta vënë një shërbim sërish në punë pasi prishet. MTTR mund të nënkuptojë gjëra paksa të ndryshme, ndaj thuaj çfarë mat.","also":["MTTR","mean time to restore","mean time to recover","koha mesatare e rikuperimit"]},{"id":"mtbf","g":"run","word":"Koha mesatare mes dështimeve (MTBF)","text":"Mesatarisht, sa kohë punon një shërbim para se të prishet diçka.","also":["MTBF","mean time between failures","koha mesatare mes dështimeve"]},{"id":"cmdb","g":"run","word":"Baza e të dhënave të konfigurimit (CMDB)","text":"Lista e të gjitha elementeve të konfigurimit dhe si lidhen mes tyre, që të shohësh çfarë varet nga çfarë.","also":["CMDB","configuration management database"]},{"id":"asset","g":"run","word":"Aktiv (asset)","text":"Çdo gjë me vlerë që e ke ose e paguan për ta mbajtur shërbimin në punë, si një laptop, një licencë softueri ose një domen.","also":["aktive","aktivi","aktivet","asset","assets"],"noTip":1},{"id":"capplan","g":"run","word":"Planifikimi i kapacitetit","text":"Sigurimi që do të ketë fuqi llogaritëse, ruajtje dhe njerëz të mjaftueshëm për atë që po vjen.","also":["capacity planning","capacity plan","plani i kapacitetit"]},{"id":"scaling","g":"run","word":"Shkallëzimi (scaling)","text":"Përballimi i më shumë përdoruesve duke i dhënë një makine më shumë fuqi (scaling up) ose duke shtuar më shumë makina (scaling out).","also":["scaling","scale up","scale out","scaling up","scaling out","shkallëzim"]},{"id":"bcp","g":"run","word":"Vazhdimësia e biznesit","text":"Plane për t'i mbajtur në këmbë gjërat e rëndësishme kur shkon keq diçka e madhe, si humbja e një zyre, e një furnitori kyç ose e kompjuterëve.","also":["vazhdimësia e biznesit","business continuity","business continuity plan"]},{"id":"dr","g":"run","word":"Rimëkëmbja pas fatkeqësisë (DR)","text":"Plani dhe mjetet për ta kthyer një shërbim pas diçkaje serioze, si humbja e një qendre të tërë të dhënash.","also":["DR","disaster recovery","rimëkëmbja pas fatkeqësisë"]},{"id":"rto","g":"run","word":"Objektivi i kohës së rikuperimit (RTO)","text":"Koha më e gjatë që një shërbim mund të jetë jashtë pune pas një fatkeqësie para se të duhet të punojë sërish.","also":["RTO","recovery time objective"]},{"id":"rpo","g":"run","word":"Objektivi i pikës së rikuperimit (RPO)","text":"Sa të dhëna të fundit mund të përballosh t'i humbasësh, e matur në kohë. Një RPO prej një ore do të thotë kopje rezervë të paktën çdo orë.","also":["RPO","recovery point objective"]},{"id":"redundancy","g":"run","word":"Redundancë (redundancy)","text":"Të kesh rezerva gati, si një server i dytë, që një dështim i vetëm të mos e ndalojë shërbimin.","also":["redundancy","redundanca","redundancë","tepricë"]},{"id":"failover","g":"run","word":"Failover","text":"Kalimi vetvetiu te një sistem rezervë kur sistemi i zakonshëm dështon.","also":["fail over","kalim automatik"]},{"id":"spof","g":"run","word":"Pikë e vetme dështimi","text":"Një pjesë që merr me vete gjithçka kur prishet, sepse nuk ka rezervë.","also":["single point of failure","single points of failure","SPOF","pika e vetme e dështimit"]},{"id":"maintwin","g":"run","word":"Dritarja e mirëmbajtjes","text":"Një kohë e planifikuar kur një shërbim mund të pezullohet ose të jetë i ngadaltë për mirëmbajtje, që u njoftohet përdoruesve paraprakisht.","also":["dritarja e mirëmbajtjes","maintenance window","maintenance windows","planned maintenance","mirëmbajtje e planifikuar"]},{"id":"handover","g":"run","word":"Dorëzimi i punës (handover)","text":"Kalimi i punës, njohurive dhe përgjegjësisë te një person ose ekip tjetër, që të mos humbasë asgjë.","also":["handover","handovers","dorëzim pune"]},{"id":"kb","g":"run","word":"Baza e njohurive","text":"Një koleksion artikujsh ndihme dhe përgjigjesh, për përdoruesit dhe për ekipin.","also":["baza e njohurive","knowledge base","knowledge bases"]},{"id":"csat","g":"run","word":"Kënaqësia e klientit (CSAT)","text":"Një notë nga përdoruesit që tregon sa të kënaqur ishin, që shpesh kërkohet pasi mbyllet një kërkesë.","also":["CSAT","customer satisfaction","kënaqësia e klientit"]},{"id":"supplier","g":"run","word":"Furnitor","text":"Një kompani e jashtme në të cilën mbështetesh, si ofruesi i hostimit. Quhet edhe vendor ose palë e tretë.","also":["furnitori","furnitorë","supplier","suppliers","vendor","vendors","third party","pala e tretë"],"noTip":1},{"id":"retire","g":"run","word":"Heqja e shërbimit nga përdorimi","text":"Fikja përgjithmonë e një shërbimi, në mënyrë të sigurt: njoftimi i përdoruesve, trajtimi i të dhënave dhe qasjes dhe ndalimi i kostove.","also":["service retirement","retiring a service","heqja e shërbimit"]},{"id":"eol","g":"run","word":"Fundi i jetës (EOL)","text":"Kur një produkt nuk merr më përditësime ose mbështetje nga prodhuesi, ndaj duhet zëvendësuar.","also":["EOL","end-of-life","end of life","fundi i jetës"]},{"id":"cybersec","g":"sec","word":"Siguria kibernetike","text":"Mbrojtja e sistemeve dhe të dhënave nga thyerja, vjedhja ose dëmtimi.","also":["siguria kibernetike","cybersecurity","cyber security"]},{"id":"authn","g":"sec","word":"Vërtetimi i identitetit (authentication)","text":"Kontrollimi se kush është dikush, zakonisht me fjalëkalim ose kod. Shpesh shkurtohet authn.","also":["authentication","authn","vërtetimi i identitetit","autentikim"]},{"id":"authz","g":"sec","word":"Autorizimi","text":"Kontrollimi i asaj që lejohet të bëjë dikush pasi e di kush është. Shpesh shkurtohet authz.","also":["authz","authorization","autorizim"]},{"id":"mfa","g":"sec","word":"Vërtetimi me shumë faktorë (MFA)","text":"Hyrja me dy ose më shumë prova, si një fjalëkalim plus një kod në telefon. Quhet edhe vërtetim me dy faktorë (2FA).","also":["MFA","2FA","two-factor","two-factor authentication","vërtetim me dy faktorë"]},{"id":"sso","g":"sec","word":"Hyrja e vetme (SSO)","text":"Identifikohesh një herë dhe hyn në shumë sisteme, si të përdorësh llogarinë e punës kudo.","also":["SSO","single sign-on","hyrje e vetme"]},{"id":"pwmgr","g":"sec","word":"Menaxher fjalëkalimesh","text":"Një aplikacion që krijon fjalëkalime të forta dhe i mban mend për ty.","also":["menaxheri i fjalëkalimeve","password manager","password managers"]},{"id":"secret","g":"sec","word":"Sekret (secret)","text":"Një fjalëkalim, çelës ose kod tjetër privat që një program e përdor për të hyrë diku. Nuk duhet ndarë kurrë dhe as shkruar në kod.","also":["sekret","sekrete","sekreti","secret","secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"Çelës API","text":"Një kod sekret që e lejon një program të përdorë API-n e një shërbimi tjetër dhe tregon kush e përdor (dhe e paguan).","also":["çelësi API","çelësat API","API key","API keys"]},{"id":"accesstoken","g":"sec","word":"Token qasjeje","text":"Një leje e përkohshme që provon se një program lejohet të hyjë, që të mos ketë nevojë për fjalëkalimin tënd çdo herë. Nuk është i njëjtë me një token AI.","also":["tokeni i qasjes","access token","access tokens"]},{"id":"encryption","g":"sec","word":"Enkriptimi","text":"Kthimi i informacionit në kod të palexueshëm, që ta lexojë vetëm dikush me çelësin e duhur.","also":["enkriptim","enkriptuar","encryption","encrypted","encrypt"]},{"id":"https","g":"sec","word":"HTTPS","text":"Mënyra e sigurt si udhëtojnë faqet e internetit, që e tregon dryni në shfletuesin tënd, që askush në mes të mos mund t'i lexojë ose t'i ndryshojë."},{"id":"cert","g":"sec","word":"Certifikatë SSL/TLS","text":"Një kartë identiteti dixhitale që e lejon një faqe interneti të provojë se kush është dhe të përdorë HTTPS. Skadon, ndaj duhet rinovuar.","also":["certifikata TLS","certifikata SSL","certifikatë","certifikata","TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"Lejet","text":"Rregullat se kush mund të shohë ose të ndryshojë çfarë.","also":["leje","lejet","permissions","permission"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Privilegji më i vogël","text":"T'i japësh çdo personi ose programi vetëm qasjen që i duhet vërtet, dhe vetëm për aq kohë sa i duhet.","also":["least privilege","principle of least privilege","parimi i privilegjit më të vogël"]},{"id":"rbac","g":"sec","word":"Kontrolli i qasjes sipas rolit (RBAC)","text":"Dhënia e qasjes sipas rolit, si shikues ose redaktues, jo person pas personi.","also":["RBAC","role-based access","role-based access control","qasje sipas rolit"]},{"id":"vuln","g":"sec","word":"Dobësi sigurie (vulnerability)","text":"Një dobësi që dikush mund ta përdorë për të hyrë pa leje ose për të bërë dëm.","also":["dobësi sigurie","dobësitë e sigurisë","cenueshmëri","cenueshmëria","vulnerabilitet","vulnerability","vulnerabilities"]},{"id":"zeroday","g":"sec","word":"Zero-day","text":"Një dobësi që sulmuesit e dinë para se prodhuesit të kenë pasur kohë ta rregullojnë.","also":["zero-days","zero day"]},{"id":"malware","g":"sec","word":"Malware","text":"Softuer i dëmshëm, si viruset, i bërë për të dëmtuar, spiunuar ose vjedhur.","also":["softuer i dëmshëm"]},{"id":"ransomware","g":"sec","word":"Ransomware","text":"Malware që të mbyll skedarët dhe kërkon para për t'i hapur. Kopjet rezervë të mira janë mbrojtja më e mirë.","also":["ransomware attack","sulm ransomware","softuer shantazhi"]},{"id":"phishing","g":"sec","word":"Phishing","text":"Mesazhe të rreme që përpiqen të të mashtrojnë të japësh fjalëkalime ose para, ose të hapësh diçka të dëmshme.","also":["phishing email","phishing emails","mashtrim me email"]},{"id":"socialeng","g":"sec","word":"Inxhinieri sociale","text":"Mashtrimi i njerëzve, jo i kompjuterëve, që të japin qasje, si një telefonatë e rreme nga “mbështetja IT”."},{"id":"firewall","g":"sec","word":"Firewall","text":"Një roje që vendos cili trafik rrjeti mund të hyjë ose të dalë.","also":["firewalls","mur zjarri"]},{"id":"vpn","g":"sec","word":"VPN","text":"Shkurtim për rrjetin privat virtual: një lidhje private e enkriptuar nëpër internet, shpesh e përdorur për të arritur sistemet e punës në mënyrë të sigurt.","also":["virtual private network","rrjet privat virtual"]},{"id":"ddos","g":"sec","word":"Mohimi i shërbimit (DoS, DDoS)","text":"Përmbytja e një shërbimi me aq trafik të rremë sa njerëzit e vërtetë nuk mund ta përdorin. DDoS do të thotë që vjen nga shumë kompjuterë njëherësh.","also":["DoS","DDoS","denial of service","DDoS attack","mohim shërbimi","sulm DDoS"]},{"id":"pentest","g":"sec","word":"Test depërtimi (pen test)","text":"Punësimi i ekspertëve miqësorë që përpiqen të hyjnë pa leje, që dobësitë të gjenden para se t'i gjejnë sulmuesit e vërtetë.","also":["pen test","pen testing","penetration testing","pentest","testim depërtimi"]},{"id":"audit","g":"sec","word":"Auditim sigurie","text":"Një kontroll i kujdesshëm se sa mirë mbrohet diçka, krahasuar me një listë praktikash të mira.","also":["auditimi i sigurisë","security audit","security audits"]},{"id":"threatmodel","g":"sec","word":"Modelimi i kërcënimeve","text":"Të mendosh se kush mund ta sulmojë diçka, si, dhe çfarë do të bëje për ta ndaluar.","also":["modelimi i kërcënimeve","threat modelling","threat model","threat modeling"]},{"id":"breach","g":"sec","word":"Cenim i të dhënave","text":"Kur informacioni privat u arrin atyre që nuk duhet ta kenë, ose humbet apo ndryshohet pa leje.","also":["cenimi i të dhënave","data breach","data breaches","rrjedhje e të dhënave"]},{"id":"pii","g":"sec","word":"Të dhëna personale","text":"Çdo informacion për një person që mund të identifikohet, si një emër, adresë emaili ose vendndodhje. Quhet edhe PII.","also":["të dhënat personale","PII","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"Ligji evropian për të dhënat personale (Mbretëria e Bashkuar ka versionin e vet): mblidh vetëm atë që të duhet, mbaje të sigurt dhe lejo njerëzit t'i shohin ose t'i fshijnë të dhënat e tyre.","also":["General Data Protection Regulation","rregullorja e përgjithshme për mbrojtjen e të dhënave"]},{"id":"dataprot","g":"sec","word":"Mbrojtja e të dhënave","text":"Kujdesi për të dhënat personale siç duhet dhe brenda ligjit.","also":["mbrojtja e të dhënave","data protection","data protection law"]},{"id":"privacypolicy","g":"sec","word":"Politika e privatësisë","text":"Një faqe publike që thotë çfarë të dhënash personale mbledh, pse, dhe çfarë bën me to.","also":["politika e privatësisë","privacy policy","privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"Pëlqimi","text":"Një “po” e qartë dhe e lirë që dikush jep që të dhënat e veta të përdoren në një mënyrë të caktuar. Mund ta tërheqë në çdo kohë.","also":["pëlqim","pëlqimi","consent","opt-in"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie","text":"Një skedar i vogël që një faqe interneti e ruan në shfletuesin tënd për të mbajtur mend gjëra, si fakti që ke hyrë në llogari. Disa kërkojnë fillimisht pëlqimin tënd.","also":["cookies","kuki"],"noTip":1},{"id":"minimisation","g":"sec","word":"Minimizimi i të dhënave","text":"Mbledhja dhe mbajtja vetëm e të dhënave personale që të duhen vërtet për punën.","also":["minimizimi i të dhënave","data minimisation","data minimization"]},{"id":"retention","g":"sec","word":"Ruajtja e të dhënave","text":"Sa kohë mbahen të dhënat para se të fshihen. Mbajtja jo më shumë se sa duhet është më e sigurt dhe shpesh e kërkuar me ligj.","also":["ruajtja e të dhënave","data retention","retention period","periudha e ruajtjes"]},{"id":"anon","g":"sec","word":"Anonimizim","text":"Ndryshimi i të dhënave që askush të mos identifikohet më në mënyrë të arsyeshme prej tyre.","also":["anonimizimi","anonimizuar","anonymisation","anonymised","anonymization","anonymous data","të dhëna anonime"]},{"id":"pseudo","g":"sec","word":"Pseudonimizim","text":"Zëvendësimi i emrave dhe detajeve të tjera me kode, me një çelës të mbajtur veçmas për t'i lidhur mbrapsht. Janë ende të dhëna personale.","also":["pseudonimizimi","pseudonimizuar","pseudonymisation","pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Marrëveshja e përpunimit të të dhënave (DPA)","text":"Një kontratë që thotë si mund t'i trajtojë një furnitor të dhënat personale në emrin tënd.","also":["DPA","data processing agreement"]},{"id":"dpia","g":"sec","word":"Vlerësimi i ndikimit në mbrojtjen e të dhënave (DPIA)","text":"Një vështrim i kujdesshëm, para se të fillosh, se si një plan për përdorimin e të dhënave personale mund të ndikojë te njerëzit dhe si të ulen rreziqet.","also":["DPIA","data protection impact assessment"]},{"id":"auditlog","g":"sec","word":"Regjistri i auditimit","text":"Një regjistrim se kush bëri çfarë dhe kur, që veprimet të kontrollohen më vonë.","also":["regjistri i auditimit","audit log","audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"Pajtueshmëria (compliance)","text":"Ndjekja e ligjeve, rregullave dhe standardeve që të vlejnë, dhe aftësia për ta provuar që i ndjek.","also":["compliance","compliant","pajtueshmëri"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"Një standard ndërkombëtar i njohur për menaxhimin e sigurisë së informacionit. Kompanitë mund të certifikohen sipas tij.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"Një raport amerikan, i kontrolluar nga audituesit e jashtëm, që tregon se një kompani i kujdeset siç duhet të dhënave të klientëve.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Agjent","text":"Një AI që punon vetë në një detyrë: lexon kodin, bën ndryshime, ekzekuton kontrolle dhe raporton mbrapsht. Puna e saj përsëri kontrollohet.","also":["agjentë","agjenti","agjentit","agjentët","agjentëve","agjentësh","agent","agents"]},{"id":"token","g":"ai","word":"Token","text":"Copëzat e vogla teksti që lexon dhe shkruan një AI, rreth tri të katërtat e një fjale secila. Përdorimi i AI numërohet në tokenë, ndaj më pak tokenë lënë më shumë nga plani yt.","also":["tokenë","tokenët","tokenëve","tokens"]},{"id":"hook","g":"ai","word":"Grep","text":"Një komandë e vogël që ekzekutohet vetë në një çast të caktuar, për shembull kur nis një sesion AI, që ekipi t'i dëgjojë komentet e tua.","also":["grepa","grepi","hook","hooks"]},{"id":"ai","g":"ai","word":"Inteligjenca artificiale (AI)","text":"Sisteme kompjuterike që bëjnë gjëra që zakonisht mendojmë se kërkojnë një njeri, si të shkruajnë, t'u përgjigjen pyetjeve ose të njohin fotografi.","also":["AI","artificial intelligence","IA","inteligjenca artificiale"],"noTip":1},{"id":"ml","g":"ai","word":"Mësimi i makinës (ML)","text":"Një mënyrë për t'i bërë kompjuterët të mësojnë modele nga shumë shembuj, në vend që t'u jepen rregulla të sakta.","also":["ML","machine learning","mësimi i makinës","mësimi automatik"]},{"id":"model","g":"ai","word":"Model","text":"“Truri” i stërvitur i një sistemi AI, i ndërtuar duke mësuar nga një numër i madh shembujsh. Modelet ndryshojnë në aftësi, shpejtësi dhe çmim.","also":["modeli","modelet","modelit","model","models","AI model","model AI"],"noTip":1},{"id":"llm","g":"ai","word":"Model i madh gjuhësor (LLM)","text":"Një model AI i stërvitur me sasi të mëdha teksti, që të mund të lexojë dhe të shkruajë tekst.","also":["LLM","LLMs","large language model","model i madh gjuhësor"]},{"id":"genai","g":"ai","word":"AI gjeneruese","text":"AI që krijon gjëra të reja, si tekst, fotografi ose kod, në vend që vetëm t'i klasifikojë ose t'i dallojë.","also":["GenAI","generative AI","AI gjeneruese"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"Një program me të cilin flet me gjuhë të përditshme, duke shkruar ose duke folur.","also":["chatbots","chatbot-e"]},{"id":"prompt","g":"ai","word":"Prompt","text":"Ajo që i jep një AI: pyetja ose udhëzimet e tua, plus çdo gjë që i dorëzon. Prompt-et më të qarta zakonisht marrin përgjigje më të mira.","also":["prompts","prompti","promptet"]},{"id":"prompteng","g":"ai","word":"Inxhinieria e prompt-eve","text":"Aftësia për të shkruar prompt-e që japin rezultate të besueshme e të dobishme.","also":["prompt engineering","inxhinieri prompt-esh"]},{"id":"sysprompt","g":"ai","word":"Prompt i sistemit","text":"Udhëzime në prapaskenë që AI merr para se të nisë biseda, që i caktojnë rolin dhe rregullat. Peshojnë më shumë se ajo që shkruan ti.","also":["prompti i sistemit","system prompt","system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"Konteksti","text":"Gjithçka që AI mund të shohë ndërsa punon: udhëzimet, mesazhet e tua, skedarët që ka lexuar dhe përgjigjet e mëparshme.","noTip":1},{"id":"ctxwin","g":"ai","word":"Dritarja e kontekstit","text":"Sa mund të mbajë mend një AI njëherësh, e matur në tokenë. Përtej kësaj, pjesët më të vjetra hidhen ose përmblidhen.","also":["dritarja e kontekstit","context window","context windows"]},{"id":"session","g":"ai","word":"Sesion","text":"Një bisedë pune me një AI, nga fillimi deri në fund. Një sesion i ri fillon me kujtesë të pastër.","also":["sesioni","sesione","sesionet","session","sessions"],"noTip":1},{"id":"memory","g":"ai","word":"Kujtesa","text":"Shënime që një AI i mban mes sesioneve, që t'i mbajë mend preferencat e tua dhe vendimet e kaluara.","noTip":1},{"id":"hallucination","g":"ai","word":"Halucinacion","text":"Kur një AI thotë diçka që tingëllon e sigurt por është e shpikur ose e gabuar. Kontrollo faktet e rëndësishme.","also":["halucinacioni","halucinacione","hallucination","hallucinations","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"Stërvitja","text":"Mësimi i një modeli duke i treguar një numër të madh shembujsh, para se ta përdorë dikush.","also":["stërvitje","stërvitja","training","trained","trajnim"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Të dhënat e stërvitjes","text":"Shembujt nga të cilët mësoi një model. Dija e tij ndalon te data kur u mblodhën ato të dhëna.","also":["të dhënat e stërvitjes","training data","training set"]},{"id":"cutoff","g":"ai","word":"Kufiri i njohurive","text":"Data ku mbaron dija e brendshme e një AI. Nuk do të dijë për gjërat e mëvonshme, përveç nëse i kërkon.","also":["kufiri i njohurive","knowledge cutoff","training cutoff"]},{"id":"finetune","g":"ai","word":"Përshtatja e imët (fine-tuning)","text":"Stërvitje shtesë e një modeli ekzistues me shembujt e tu, që ta bësh më të mirë në një punë të caktuar.","also":["fine-tuning","fine-tune","fine-tuned","fine tuning","përshtatje e imët"]},{"id":"inference","g":"ai","word":"Inferenca (inference)","text":"Një model AI që përdoret realisht për t'iu përgjigjur diçkaje, ndryshe nga stërvitja.","also":["inference","model inference","inferencë","inferenca"]},{"id":"tooluse","g":"ai","word":"Përdorimi i mjeteve","text":"Një AI që mund të bëjë gjëra, jo vetëm të flasë: të ekzekutojë komanda, të lexojë skedarë ose të kërkojë në ueb, nëpërmjet mjeteve që i jep aplikacioni.","also":["përdorimi i mjeteve","tool use","tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"Nënagjent","text":"Një AI ndihmëse të cilës një AI kryesore i jep një punë më të vogël dhe merr rezultatin mbrapsht.","also":["nënagjenti","nënagjentë","subagent","subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"Shumëagjent","text":"Disa AI që punojnë bashkë në një punë, secila me pjesën e vet, si një ekip i vogël.","also":["multi-agent","multi-agent system","sistem shumëagjent"]},{"id":"autonomy","g":"ai","word":"Autonomia","text":"Sa mund të bëjë një AI vetë para se të duhet të pyesë një njeri.","also":["autonomia","autonomi","autonomy","autonomous"]},{"id":"hitl","g":"ai","word":"Njeriu në qark (human in the loop)","text":"Mbajtja e një njeriu të përfshirë për të kontrolluar ose miratuar atë që bën AI në pika kyç. Në AI-gile ky je ti.","also":["human in the loop","human-in-the-loop","HITL","njeriu në qark"]},{"id":"guardrails","g":"ai","word":"Kufizime sigurie (guardrails)","text":"Kufij dhe kontrolle që i mbajnë të sigurta veprimet e një AI, si kërkimi i miratimit para se diçka të dalë live. Ulin rrezikun e gabimeve, por nuk i përjashtojnë.","also":["guardrails","guardrail","kufizimet e sigurisë"]},{"id":"rag","g":"ai","word":"Gjenerim i pasuruar me kërkim (RAG)","text":"Ta lësh një AI të kërkojë në dokumentet e tua para se të përgjigjet, që përgjigjet e saj të mbështeten te faktet e tua.","also":["RAG","retrieval augmented generation","retrieval-augmented generation"]},{"id":"embedding","g":"ai","word":"Embedding","text":"Kthimi i tekstit në një listë numrash që kap kuptimin e tij, që një kompjuter të gjejë gjëra që kanë kuptim të ngjashëm.","also":["embeddings","vektor kuptimi"]},{"id":"vectordb","g":"ai","word":"Bazë të dhënash vektoriale","text":"Një bazë të dhënash e ndërtuar për të kërkuar në ato lista numrash (embeddings), për të gjetur material me kuptim të ngjashëm.","also":["baza të dhënash vektoriale","vector database","vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"Një mënyrë e përbashkët për t'i lidhur mjetet dhe burimet e të dhënave me aplikacionet AI, që një AI t'i përdorë.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Temperatura","text":"Një cilësim për sa e guximshme është përgjigjja e një AI. E ulët jep përgjigje më të qëndrueshme dhe më të parashikueshme; e lartë jep më të larmishme. Asnjëra nuk e bën gjithmonë të saktë.","also":["temperatura","temperature","model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodal","text":"I aftë të punojë me më shumë se një lloj informacioni, si teksti, fotot dhe zëri.","also":["multi-modal","shumëmodal"]},{"id":"evals","g":"ai","word":"Vlerësim (eval)","text":"Një provë e planifikuar se sa mirë ia del një AI me shembuj të zgjedhur, që të krahasosh modele ose prompt-e.","also":["eval","evals","evaluation","vlerësimi"]},{"id":"bias","g":"ai","word":"Paragjykim (bias)","text":"Kur një AI (ose një njeri) anon padrejtësisht nga një anë, shpesh për shkak të asaj nga e cila ka mësuar.","also":["bias","biased","paragjykimi","njëanshmëri"],"noTip":1},{"id":"responsible","g":"ai","word":"AI e përgjegjshme","text":"Përdorimi i AI në mënyrë të drejtë, të sigurt dhe të ndershme, me njerëzit që mbeten përgjegjës për rezultatet.","also":["responsible AI","ethical AI","AI etike"]},{"id":"injection","g":"ai","word":"Prompt injection","text":"Një dredhi ku udhëzime të fshehura në një faqe interneti ose skedar përpiqen ta bëjnë një AI të bëjë diçka që përdoruesi i saj nuk e ka kërkuar.","also":["prompt injections","injektim prompt-i"]},{"id":"ratelimit","g":"ai","word":"Kufiri i kërkesave (rate limit)","text":"Një tavan se sa kërkesa mund t'i dërgosh një shërbimi në një kohë të caktuar. Nëse e kalon, duhet të presësh.","also":["rate limit","rate limits","rate limited","kufiri i kërkesave"]},{"id":"usagelimit","g":"ai","word":"Kufiri i përdorimit","text":"Sa punë AI lejon plani yt në një periudhë, pas së cilës pezullohet ose kushton më shumë.","also":["kufiri i përdorimit","usage limit","usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Ndërtimi i softuerit kryesisht duke i përshkruar një AI çfarë do dhe duke e lënë të shkruajë kodin.","also":["vibe-coding"]},{"id":"budget","g":"money","word":"Buxhet","text":"Shuma e parave e ndarë për diçka.","also":["buxheti","buxhete","buxhetet","budget","budgets"],"noTip":1},{"id":"costest","g":"money","word":"Vlerësim kostoje","text":"Një hamendje e mirë se sa do të kushtojë diçka para se të fillosh.","also":["vlerësimi i kostos","cost estimate","cost estimates"]},{"id":"roi","g":"money","word":"Kthimi i investimit (ROI)","text":"Ajo që merr mbrapsht krahasuar me atë që vure. Nëse del pozitiv, ia vlente.","also":["ROI","return on investment","kthimi i investimit"]},{"id":"tco","g":"money","word":"Kosto totale e pronësisë (TCO)","text":"Gjithçka që kushton vërtet diçka gjatë gjithë jetës, jo vetëm çmimi i blerjes: përdorimi, mbështetja, përmirësimet dhe në fund heqja nga përdorimi.","also":["TCO","total cost of ownership","kosto totale e pronësisë"]},{"id":"capex","g":"money","word":"CapEx dhe OpEx","text":"CapEx janë paratë e shpenzuara paraprakisht për gjëra që i mban; OpEx është shpenzimi i vazhdueshëm, si faturat mujore.","also":["CapEx","OpEx","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Abonim","text":"Pagesa e rregullt, zakonisht çdo muaj ose çdo vit, për të vazhduar ta përdorësh diçka.","also":["abonimi","abonime","abonimet","subscription","subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"Softuer si shërbim (SaaS)","text":"Softuer që e përdor online dhe e paguan me abonim, ndërsa prodhuesi e drejton për ty.","also":["SaaS","software as a service","softuer si shërbim"]},{"id":"payg","g":"money","word":"Paguaj sa përdor","text":"Paguan vetëm për atë që përdor, si te shërbimet cloud ose tokenët e AI.","also":["pay as you go","pay-as-you-go","usage-based pricing","paguaj sa përdor"]},{"id":"overage","g":"money","word":"Tejkalim","text":"Përdorim mbi atë që përfshin plani yt, që mund të kushtojë shtesë.","also":["tejkalimi","tejkalime","overage","overages","overage charges"]},{"id":"billingalert","g":"money","word":"Alarm faturimi","text":"Një mesazh kur shpenzimi ose përdorimi arrin një nivel që ke zgjedhur. Të paralajmëron, por jo gjithmonë i ndalon pagesat e mëtejshme.","also":["alarmi i faturimit","billing alert","billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"Niveli falas","text":"Një nivel falas i një shërbimi me pagesë, me kufij. I dobishëm për të nisur.","also":["niveli falas","plani falas","free tier","free plan"]},{"id":"pricing","g":"money","word":"Plani i çmimeve","text":"Paketat e ndryshme që shet një shërbim, secila me çmimin dhe kufijtë e vet.","also":["plani i çmimeve","planet e çmimeve","pricing plan","pricing plans","price plan"]},{"id":"licence","g":"money","word":"Licencë","text":"Rregullat se si mund ta përdorësh, kopjosh, ndryshosh ose ndash diçka që e ka bërë dikush tjetër, si softueri, shkronjat ose fotot.","also":["licenca","licencat","licencës","licence","licences","license","licenses"],"noTip":1},{"id":"opensource","g":"money","word":"Kod i hapur (open source)","text":"Softuer kodin e të cilit mund ta lexojë, ta përdorë dhe shpesh ta ndryshojë kushdo falas, sipas rregullave të licencës së tij.","also":["open source","open-source","open source software","OSS","kod i hapur","softuer me kod të hapur"]},{"id":"osslicence","g":"money","word":"Licencë open source","text":"Rregullat që vijnë me kodin open source. Disa të lejojnë pothuajse gjithçka (si MIT); disa kërkojnë që t'i ndash edhe ndryshimet e tua (si GPL).","also":["licenca open source","open source licence","open source licences","MIT licence","GPL"]},{"id":"proprietary","g":"money","word":"Pronësor (proprietary)","text":"I zotëruar nga një kompani dhe jo i lirë për t'u kopjuar ose ndryshuar. E kundërta e open source.","also":["proprietary","proprietary software","softuer pronësor"]},{"id":"copyright","g":"money","word":"E drejta e autorit","text":"E drejta ligjore e një krijuesi për të kontrolluar kopjet e punës së vet, përfshirë kodin dhe shkrimet.","also":["e drejta e autorit","copyright","copyrighted","të drejtat e autorit"],"noTip":1},{"id":"ip","g":"money","word":"Pronësia intelektuale (IP)","text":"Ide dhe krijime që ligji i trajton si të zotëruara, si kodi, dizajnet, emrat dhe logot.","also":["IP","intellectual property","pronësia intelektuale"]},{"id":"tos","g":"money","word":"Kushtet e shërbimit","text":"Rregullat që i pranon kur përdor një shërbim.","also":["kushtet e shërbimit","terms of service","terms and conditions","terms of use","kushtet e përdorimit"]},{"id":"contract","g":"money","word":"Kontratë","text":"Një marrëveshje e shkruar mes dy palëve që ligji do ta mbështesë.","also":["kontrata","kontratat","kontratës","contract","contracts"],"noTip":1},{"id":"sow","g":"money","word":"Deklarata e punës (SOW)","text":"Një dokument që përcakton saktësisht çfarë pune do të bëhet, deri kur dhe për sa para.","also":["SOW","statement of work","deklarata e punës"]},{"id":"fixedprice","g":"money","word":"Çmim fiks","text":"Një çmim i dakordësuar për gjithë punën, sido që të zgjasë.","also":["çmimi fiks","fixed price","fixed-price"]},{"id":"tm","g":"money","word":"Kohë dhe materiale","text":"Pagesa për orët e punuara realisht dhe gjërat e përdorura realisht, jo një çmim i caktuar.","also":["T&M","time and materials","kohë dhe materiale"]},{"id":"invoice","g":"money","word":"Faturë","text":"Një llogari që kërkon pagesë për punën e bërë ose mallrat e furnizuara.","also":["fatura","faturat","invoice","invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Varësi nga furnitori (lock-in)","text":"Kur largimi nga një furnitor është aq i vështirë ose i kushtueshëm sa nuk mund të shkëputesh prej tij.","also":["vendor lock-in","lock-in","varësia nga furnitori"]},{"id":"procurement","g":"money","word":"Prokurimi","text":"Procesi i zgjedhjes dhe blerjes nga furnitorët.","also":["prokurim","prokurimi","procurement"]},{"id":"servicecredit","g":"money","word":"Kredi shërbimi","text":"Kthim parash ose zbritje që merr kur një furnitor nuk e përmbush SLA-në.","also":["kredia e shërbimit","service credit","service credits"]}]}};
